  LS.lessons["c-accounting-equation"] = {
    id: "c-accounting-equation", minutes: 5,
    title: "Accounting equation",
    short: "Accounting equation",
    desc: "Everything a business owns was paid for by someone — either a lender or an owner.",
    lede: "The accounting equation says that everything a business has was funded by somebody, and there are only two somebodies: people it owes money to, and its owners.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "The accounting equation says that everything a business has was funded by somebody, and there are only two somebodies: people it owes money to, and its owners. So the value of what it has must equal the claims against it. This is not a rule accountants invented and enforce — it is true by construction, because you cannot acquire something without a source of funding." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "This equation is the skeleton of the balance sheet and the reason accounts balance at all. Once you can see it, the balance sheet stops being an intimidating table and becomes a simple statement of what a business has and who paid for it." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Assets are everything the business controls.<br><br>2. Liabilities are claims from everyone who is not an owner.<br><br>3. Equity is the owners' residual claim — whatever is left.<br><br>4. Every transaction changes at least two items, and the equation still holds afterwards." },
      { t: "formula", title: "The structural relationship every balance sheet must satisfy", lines: ["<b>Assets = Liabilities + Equity</b>", "Assets = Everything the business controls and expects future benefit from", "Liabilities = Everything owed to non-owners", "Equity = The owners' residual claim"] },
      { t: "example", h: "<p>You start a business, then make three moves.</p><ol><li>You invest ₹10,00,000 cash. Assets +₹10,00,000; Equity +₹10,00,000. Equation holds.</li><li>You borrow ₹5,00,000. Assets +₹5,00,000 (cash); Liabilities +₹5,00,000. Total assets ₹15,00,000 = ₹5,00,000 + ₹10,00,000.</li><li>You buy an oven for ₹4,00,000 cash. Assets −₹4,00,000 cash, +₹4,00,000 equipment. Total unchanged at ₹15,00,000.</li></ol><p><strong>What it means.</strong> The third move changed the shape of the assets but not the total, and touched neither liabilities nor equity. Swapping one asset for another creates no profit — a point that trips up almost every beginner.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Balance sheet", h: "The statement showing assets, liabilities and equity at one point in time." },
      { t: "def", term: "Residual claim", h: "What owners hold — whatever remains after other claims." },
      { t: "def", term: "Transaction", h: "An economic event that the accounts record." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "You invest ₹10,00,000, then the business borrows ₹5,00,000, then buys an oven for ₹4,00,000 cash. State assets, liabilities and equity after each step.", a: "After investing: A 10L = L 0 + E 10L. After borrowing: A 15L = L 5L + E 10L. After the oven: assets are ₹11L cash + ₹4L equipment = 15L — composition changed, totals did not." }, { q: "Assets ₹120 crore, equity ₹45 crore. Liabilities?", a: "L = A − E = ₹75 crore. The equation can always be solved for its third member." }, { q: "A firm buys ₹2,00,000 of inventory on supplier credit. Which sides of the equation move, and does profit change?", a: "Assets +₹2,00,000 (inventory) and liabilities +₹2,00,000 (payable). Equity and profit are untouched — nothing has been sold yet." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "balance", title: "Equation sandbox", prompt: "Change either side and note that equity is forced — it is computed, never chosen.", fields: [{ key: "assets", label: "Assets", value: 1500000, unit: "₹" }, { key: "liabilities", label: "Liabilities", value: 500000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Assets always equal liabilities plus equity.<br>• Every transaction preserves the equation.<br>• Exchanging one asset for another changes composition, not total value, and creates no profit." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Thinking every transaction affects profit.<br><br>Believing accountants force the balance sheet to balance — it balances because of how it is defined." },
      { t: "mcq", q: "The accounting equation states…", opts: ["Revenue = Costs + Profit", "Assets = Liabilities + Equity", "Cash = Profit", "Debits = Assets"], correct: 1, why: ["Not this one. Everything the business has was funded by lenders or owners — true by construction, not by enforcement.", "Correct. Everything the business has was funded by lenders or owners — true by construction, not by enforcement.", "Not this one. Everything the business has was funded by lenders or owners — true by construction, not by enforcement.", "Not this one. Everything the business has was funded by lenders or owners — true by construction, not by enforcement."] },
      { t: "mcq", q: "Buying equipment for cash…", opts: ["Increases total assets", "Decreases equity", "Leaves totals unchanged — one asset swaps for another", "Creates profit"], correct: 2, why: ["Not this one. Cash down, equipment up, same total. Beginners often expect a profit effect; there is none.", "Not this one. Cash down, equipment up, same total. Beginners often expect a profit effect; there is none.", "Correct. Cash down, equipment up, same total. Beginners often expect a profit effect; there is none.", "Not this one. Cash down, equipment up, same total. Beginners often expect a profit effect; there is none."] },
      { t: "mcq", q: "If liabilities rise ₹5 crore with no change in equity, assets must…", opts: ["Fall ₹5 crore", "Rise ₹5 crore", "Stay fixed", "Double"], correct: 1, why: ["Not this one. The equation must keep holding — borrowed money arrives as an asset (usually cash).", "Correct. The equation must keep holding — borrowed money arrives as an asset (usually cash).", "Not this one. The equation must keep holding — borrowed money arrives as an asset (usually cash).", "Not this one. The equation must keep holding — borrowed money arrives as an asset (usually cash)."] }
    ]
  };

  LS.lessons["c-double-entry-accounting"] = {
    id: "c-double-entry-accounting", minutes: 5,
    title: "Double-entry accounting",
    short: "Double-entry accounting",
    desc: "Recording both sides of every transaction, so nothing appears from nowhere.",
    lede: "Every business event has two sides.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Every business event has two sides. If cash leaves, something must have been received. If a sale is made, something must have been given up. Double-entry accounting simply insists that you record both sides. Doing so keeps the accounting equation intact automatically and makes many errors self-revealing." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Double entry is why financial statements tie together. If you understand that each event has two sides, the connection between the income statement, balance sheet and cash flow statement becomes obvious rather than mysterious." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Identify the real-world event first, before reaching for any accounting label.<br><br>2. Ask what the business received and what it gave up.<br><br>3. Record both, in equal amounts.<br><br>4. Confirm that assets still equal liabilities plus equity." },
      { t: "example", h: "<p>Four ordinary events at a bakery.</p><ol><li>Buy flour for ₹20,000 cash: inventory up ₹20,000, cash down ₹20,000. Assets swap; no profit.</li><li>Buy flour for ₹20,000 on 30-day credit: inventory up ₹20,000, amount owed to supplier up ₹20,000.</li><li>Sell bread for ₹5,000 cash that cost ₹2,000 to make: cash up ₹5,000, inventory down ₹2,000, equity up ₹3,000 via profit.</li><li>Repay ₹20,000 to the supplier: cash down ₹20,000, amount owed down ₹20,000.</li></ol><p><strong>What it means.</strong> Only the third event produced profit, because only there did the business give up something worth less than what it received. The other three rearranged the balance sheet.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Double entry", h: "Recording both sides of every transaction in equal amounts." },
      { t: "def", term: "Journal entry", h: "The written record of one transaction's two sides." },
      { t: "def", term: "Ledger", h: "The collection of all accounts where entries accumulate." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Record both sides: a bakery buys ₹20,000 of flour with cash; then a second batch on 30-day credit.", a: "Cash purchase: inventory +20,000, cash −20,000. Credit purchase: inventory +20,000, payable +20,000. Neither touches profit." }, { q: "Bread costing ₹2,000 sells for ₹5,000 cash. Record every movement.", a: "Cash +5,000; inventory −2,000; equity +3,000 through profit. Profit appears because what was received exceeds what was given up." }, { q: "Why does repaying a ₹20,000 supplier invoice create no expense?", a: "The expense (or asset) was recorded when the goods arrived. Payment merely settles the liability: cash −20,000, payable −20,000." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Every transaction is recorded twice, in equal amounts.<br>• Start from the business event, not from the accounting terminology.<br>• Profit arises only when what you receive is worth more than what you give up." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Memorising rules without understanding the underlying event.<br><br>Assuming cash movement and profit are the same thing." },
      { t: "mcq", q: "Double-entry requires every transaction to…", opts: ["Be approved twice", "Record what was received and what was given up, in equal amounts", "Involve cash", "Create profit"], correct: 1, why: ["Not this one. Two sides, equal amounts — which is what keeps the accounting equation intact automatically.", "Correct. Two sides, equal amounts — which is what keeps the accounting equation intact automatically.", "Not this one. Two sides, equal amounts — which is what keeps the accounting equation intact automatically.", "Not this one. Two sides, equal amounts — which is what keeps the accounting equation intact automatically."] },
      { t: "mcq", q: "Which event creates profit?", opts: ["Buying stock with cash", "Borrowing money", "Selling goods for more than they cost", "Repaying a loan"], correct: 2, why: ["Not this one. Only receiving more value than is given up creates profit. The others rearrange the balance sheet.", "Not this one. Only receiving more value than is given up creates profit. The others rearrange the balance sheet.", "Correct. Only receiving more value than is given up creates profit. The others rearrange the balance sheet.", "Not this one. Only receiving more value than is given up creates profit. The others rearrange the balance sheet."] },
      { t: "mcq", q: "The right starting point for any entry is…", opts: ["The debit/credit rule table", "The real-world event and its two sides", "The tax code", "The bank statement"], correct: 1, why: ["Not this one. Identify what happened economically first; the bookkeeping labels then follow naturally.", "Correct. Identify what happened economically first; the bookkeeping labels then follow naturally.", "Not this one. Identify what happened economically first; the bookkeeping labels then follow naturally.", "Not this one. Identify what happened economically first; the bookkeeping labels then follow naturally."] }
    ]
  };

  LS.lessons["c-debits-and-credits"] = {
    id: "c-debits-and-credits", minutes: 5,
    title: "Debits and credits",
    short: "Debits and credits",
    desc: "The two labels accountants use for the two sides of an entry. Neither means good or bad.",
    lede: "Debit and credit are just names for the left and right side of a journal entry.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Debit and credit are just names for the left and right side of a journal entry. That is genuinely all they are. They do not mean increase and decrease, and they do not mean good and bad. Whether a debit raises or lowers an account depends entirely on what kind of account it is." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "The vocabulary confuses beginners more than the concept does, largely because a bank statement uses the words from the bank's point of view — the opposite of yours. Getting this straight early removes a persistent source of confusion." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Debits increase assets and expenses; credits decrease them.<br><br>2. Credits increase liabilities, equity and revenue; debits decrease them.<br><br>3. Every entry must have total debits equal to total credits.<br><br>4. Your bank 'crediting' your account records a liability increase in the bank's books — it owes you more. The words are from the bank's perspective, not yours." },
      { t: "example", h: "<p>A business sells ₹50,000 of goods for cash and pays ₹8,000 rent.</p><ol><li>Sale: debit cash ₹50,000 (an asset increases), credit revenue ₹50,000. Debits = credits.</li><li>Rent: debit rent expense ₹8,000 (an expense increases), credit cash ₹8,000 (an asset decreases).</li><li>Net effect on cash: +₹50,000 − ₹8,000 = +₹42,000.</li></ol><p><strong>What it means.</strong> Cash was debited in one entry and credited in the other. The same account moved in both directions depending on what happened — which is why 'debit means increase' is wrong as a general rule.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Debit", h: "The left side of an entry. Increases assets and expenses." },
      { t: "def", term: "Credit", h: "The right side of an entry. Increases liabilities, equity and revenue." },
      { t: "def", term: "Trial balance", h: "A check that total debits equal total credits across all accounts." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Write the entries: a sale of ₹50,000 for cash, then ₹8,000 rent paid.", a: "Sale: debit cash 50,000; credit revenue 50,000. Rent: debit rent expense 8,000; credit cash 8,000." }, { q: "In those two entries, cash was debited once and credited once. What does that tell you about 'debit = increase'?", a: "Debits increase assets (cash rose on the sale) and credits decrease them (cash fell for rent). The effect depends on the account type, not the word." }, { q: "Your bank SMS says your account was 'credited ₹10,000'. Translate into whose books that language belongs to.", a: "The bank's. Your deposit is the bank's liability; crediting it records that the bank owes you more. In your own books, your cash would be debited." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Debit and credit mean left and right, nothing more.<br>• The effect depends on the account type, not on the word.<br>• Total debits must always equal total credits." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Reading credit as good and debit as bad.<br><br>Carrying bank-statement intuition into accounting — the bank writes from its own perspective." },
      { t: "mcq", q: "Debit and credit fundamentally mean…", opts: ["Bad and good", "Decrease and increase", "The left and right side of an entry", "Cash out and cash in"], correct: 2, why: ["Not this one. They are positional labels. Their effect depends entirely on the account family involved.", "Not this one. They are positional labels. Their effect depends entirely on the account family involved.", "Correct. They are positional labels. Their effect depends entirely on the account family involved.", "Not this one. They are positional labels. Their effect depends entirely on the account family involved."] },
      { t: "mcq", q: "A debit increases…", opts: ["Liabilities and revenue", "Assets and expenses", "Equity only", "Everything"], correct: 1, why: ["Not this one. Assets and expenses grow with debits; liabilities, equity and revenue grow with credits.", "Correct. Assets and expenses grow with debits; liabilities, equity and revenue grow with credits.", "Not this one. Assets and expenses grow with debits; liabilities, equity and revenue grow with credits.", "Not this one. Assets and expenses grow with debits; liabilities, equity and revenue grow with credits."] },
      { t: "mcq", q: "In every journal entry…", opts: ["Debits exceed credits", "Total debits equal total credits", "Only one account moves", "Cash must appear"], correct: 1, why: ["Not this one. Equality of debits and credits is the mechanical guarantee behind the trial balance.", "Correct. Equality of debits and credits is the mechanical guarantee behind the trial balance.", "Not this one. Equality of debits and credits is the mechanical guarantee behind the trial balance.", "Not this one. Equality of debits and credits is the mechanical guarantee behind the trial balance."] }
    ]
  };

  LS.lessons["c-chart-of-accounts"] = {
    id: "c-chart-of-accounts", minutes: 5,
    title: "Chart of accounts",
    short: "Chart of accounts",
    desc: "The organised list of buckets a business sorts every transaction into.",
    lede: "A chart of accounts is the list of categories a business uses to file its transactions — cash, inventory, salaries, sales, loans, and so on.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "A chart of accounts is the list of categories a business uses to file its transactions — cash, inventory, salaries, sales, loans, and so on. Every transaction must land in one of them. It is essentially a filing system, and how well it is designed determines whether the resulting reports can answer useful questions." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Financial statements are just the chart of accounts totalled and arranged. If the categories are too coarse, no amount of later analysis can recover the detail. If they are too fine, nobody maintains them properly." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Accounts are grouped into five families: assets, liabilities, equity, revenue and expenses.<br><br>2. The first three appear on the balance sheet; the last two appear on the income statement.<br><br>3. Each account usually has a code, so related accounts sort together.<br><br>4. Design follows the questions management needs answered — split revenue by product only if someone will act on it." },
      { t: "example", h: "<p>A small café's chart of accounts, in outline.</p><ol><li>Assets: 1000 Cash · 1100 Receivables · 1200 Inventory · 1500 Equipment.</li><li>Liabilities: 2000 Supplier payables · 2100 Salaries payable · 2500 Bank loan.</li><li>Equity: 3000 Owner capital · 3100 Retained earnings.</li><li>Revenue: 4000 Coffee sales · 4100 Food sales. Expenses: 5000 Ingredients · 5100 Salaries · 5200 Rent.</li></ol><p><strong>What it means.</strong> Because coffee and food sales are separate accounts, the owner can see which line is growing. Had both been booked to one 'Sales' account, that question would be unanswerable without re-reading every receipt.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Account", h: "A single category that transactions are recorded into." },
      { t: "def", term: "Account code", h: "A number that groups and orders related accounts." },
      { t: "def", term: "General ledger", h: "The complete set of accounts and their balances." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Assign each to its family: Coffee sales · Bank loan · Espresso machine · Ingredient costs · Owner capital.", a: "Revenue · Liability · Asset · Expense · Equity — the five families every account belongs to." }, { q: "A café books coffee and food sales into one 'Sales' account. What question becomes unanswerable, and what is the fix?", a: "Which line is growing. Split into separate revenue accounts (e.g. 4000 Coffee, 4100 Food) so reports carry the distinction." }, { q: "Why is a 200-account chart sometimes worse than a 40-account one?", a: "Detail nobody maintains gets used inconsistently, corrupting every report built on it. Capture the distinctions someone will act on — no more." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "The chart of accounts is the filing system behind the financial statements.<br>• Five families: assets, liabilities, equity, revenue, expenses.<br>• The detail you capture now sets a ceiling on the analysis you can do later." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Creating so many accounts that they are used inconsistently.<br><br>Lumping unrelated costs into a single 'miscellaneous' account." },
      { t: "mcq", q: "The chart of accounts is best described as…", opts: ["A payment schedule", "The filing system every transaction is sorted into", "A tax form", "The audit report"], correct: 1, why: ["Not this one. Financial statements are the chart's accounts totalled and arranged — the filing design caps the analysis.", "Correct. Financial statements are the chart's accounts totalled and arranged — the filing design caps the analysis.", "Not this one. Financial statements are the chart's accounts totalled and arranged — the filing design caps the analysis.", "Not this one. Financial statements are the chart's accounts totalled and arranged — the filing design caps the analysis."] },
      { t: "mcq", q: "The five account families are…", opts: ["Cash, bank, card, loan, tax", "Assets, liabilities, equity, revenue, expenses", "Sales, costs, profit, dividends, reserves", "Current, fixed, tangible, intangible, other"], correct: 1, why: ["Not this one. Three balance-sheet families and two income-statement families cover everything.", "Correct. Three balance-sheet families and two income-statement families cover everything.", "Not this one. Three balance-sheet families and two income-statement families cover everything.", "Not this one. Three balance-sheet families and two income-statement families cover everything."] },
      { t: "mcq", q: "Recording detail 'just in case', with no one to act on it, tends to…", opts: ["Improve accuracy", "Cause inconsistent use and unreliable reports", "Reduce audit fees", "Speed up closing"], correct: 1, why: ["Not this one. Account design should follow the decisions it must support.", "Correct. Account design should follow the decisions it must support.", "Not this one. Account design should follow the decisions it must support.", "Not this one. Account design should follow the decisions it must support."] }
    ]
  };

  LS.lessons["c-accrual-accounting"] = {
    id: "c-accrual-accounting", minutes: 5,
    title: "Accrual accounting",
    short: "Accrual accounting",
    desc: "Recording activity when it happens economically, not when the cash moves.",
    lede: "Accrual accounting records revenue when the business delivers what it promised, and records costs in the period they relate to — regardless of when money changes hands.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Accrual accounting records revenue when the business delivers what it promised, and records costs in the period they relate to — regardless of when money changes hands. The goal is to show what happened in a period, rather than what happened to be paid during it." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Almost every set of published accounts you will read is prepared on this basis, and it is the single biggest reason profit and cash differ. Understanding accruals is what lets you read a profit figure without being misled by it." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Revenue is recorded when the goods or services are delivered.<br><br>2. Costs are matched to the revenue or period they relate to.<br><br>3. If cash arrives before delivery, the business owes the customer a service — recorded as a liability, not revenue.<br><br>4. If delivery happens before cash arrives, the business is owed money — recorded as a receivable." },
      { t: "example", h: "<p>In December, a consultant completes ₹4,00,000 of work, invoices it, and is paid in February. She also pays ₹1,20,000 in December for a year of insurance starting in January.</p><ol><li>December revenue: ₹4,00,000 is recorded, because the work was done. A ₹4,00,000 receivable is created.</li><li>December cash from that work: nil.</li><li>December insurance expense: nil. The ₹1,20,000 buys next year's cover, so it sits as a prepaid asset.</li><li>Each month of the next year, ₹10,000 moves from the prepaid asset into expense.</li></ol><p><strong>What it means.</strong> December shows ₹4,00,000 of profit and a cash outflow of ₹1,20,000. Both are correct; they answer different questions. Accruals describe activity, cash describes liquidity.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Accrual", h: "Recording an economic event when it occurs rather than when cash moves." },
      { t: "def", term: "Matching", h: "Recording costs in the same period as the revenue they helped generate." },
      { t: "def", term: "Prepaid expense", h: "Cash paid in advance for a benefit not yet received." },
      { t: "def", term: "Deferred revenue", h: "Cash received in advance for something not yet delivered." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A consultant finishes ₹4,00,000 of work in December, paid in February. What do December and February each show under accrual accounting?", a: "December: revenue ₹4,00,000 and a receivable ₹4,00,000. February: cash +4,00,000, receivable cleared — no new revenue." }, { q: "She also pays ₹1,20,000 in December for insurance covering January–December next year. December's expense?", a: "Nil. The payment creates a ₹1,20,000 prepaid asset, released at ₹10,000/month across the covered year." }, { q: "Combine both: what are December's profit and December's cash movement?", a: "Profit +₹4,00,000 (revenue, no matching expense yet); cash −₹1,20,000. Both correct — they answer different questions." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "accrual-timing", title: "Delivery vs collection sandbox", prompt: "Set collections above delivery, then below. Watch which balance-sheet item each gap creates.", fields: [{ key: "workDelivered", label: "Work delivered this month", value: 400000, unit: "₹" }, { key: "cashCollected", label: "Cash collected this month", value: 150000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Accrual accounting records economic activity, not cash timing.<br>• It is the main reason profit differs from cash flow.<br>• Cash received before delivery is a liability, not revenue." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Reading accrual profit as cash generated.<br><br>Recording revenue on receipt of a customer deposit." },
      { t: "mcq", q: "Accrual accounting records revenue when…", opts: ["Cash arrives", "The contract is signed", "The promised goods or services are delivered", "The invoice is printed"], correct: 2, why: ["Not this one. Delivery is the earning event. Cash timing is tracked separately, via receivables and deferred revenue.", "Not this one. Delivery is the earning event. Cash timing is tracked separately, via receivables and deferred revenue.", "Correct. Delivery is the earning event. Cash timing is tracked separately, via receivables and deferred revenue.", "Not this one. Delivery is the earning event. Cash timing is tracked separately, via receivables and deferred revenue."] },
      { t: "mcq", q: "Cash received before delivering the service is recorded as…", opts: ["Revenue", "A liability (deferred revenue)", "Equity", "A prepaid expense"], correct: 1, why: ["Not this one. The business owes the customer performance; until delivered, the money is an obligation, not an achievement.", "Correct. The business owes the customer performance; until delivered, the money is an obligation, not an achievement.", "Not this one. The business owes the customer performance; until delivered, the money is an obligation, not an achievement.", "Not this one. The business owes the customer performance; until delivered, the money is an obligation, not an achievement."] },
      { t: "mcq", q: "The main reason reported profit differs from cash flow is…", opts: ["Arithmetic errors", "Accrual timing of revenue and costs", "Currency movements", "Auditor adjustments"], correct: 1, why: ["Not this one. Accruals deliberately separate activity from payment timing — the divergence is the design, not a flaw.", "Correct. Accruals deliberately separate activity from payment timing — the divergence is the design, not a flaw.", "Not this one. Accruals deliberately separate activity from payment timing — the divergence is the design, not a flaw.", "Not this one. Accruals deliberately separate activity from payment timing — the divergence is the design, not a flaw."] }
    ]
  };

  LS.lessons["c-cash-accounting"] = {
    id: "c-cash-accounting", minutes: 5,
    title: "Cash accounting",
    short: "Cash accounting",
    desc: "The simpler alternative: record everything when money actually moves.",
    lede: "Cash accounting records revenue when payment is received and costs when payment is made.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Cash accounting records revenue when payment is received and costs when payment is made. It is simple, requires no judgement about timing, and matches the bank statement exactly. Its weakness is that it can badly misrepresent a period's activity." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Very small businesses often use it, and some tax regimes permit it. More importantly, understanding it by contrast is what makes accrual accounting click." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Money in is revenue on the day it arrives.<br><br>2. Money out is expense on the day it leaves.<br><br>3. No receivables, payables, prepayments or deferred revenue exist.<br><br>4. Timing of payments, rather than timing of activity, drives reported results." },
      { t: "example", h: "<p>The same consultant from the previous lesson: ₹4,00,000 of December work paid in February, ₹1,20,000 of insurance paid in December for next year.</p><ol><li>Cash basis December: revenue nil, expense ₹1,20,000, result = ₹1,20,000 loss.</li><li>Cash basis February: revenue ₹4,00,000, no related cost, result = ₹4,00,000 profit.</li><li>Accrual basis December: revenue ₹4,00,000, insurance expense nil, result = ₹4,00,000 profit.</li></ol><p><strong>What it means.</strong> Cash accounting reports a loss in the month she did all the work and a large profit in a month she did none. Nothing was recorded incorrectly — the method simply tracks payment dates rather than activity.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Cash basis", h: "Recording transactions only when money moves." },
      { t: "def", term: "Accrual basis", h: "Recording transactions when the economic event occurs." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Using cash accounting, restate the consultant's December (₹4,00,000 of work paid in February; ₹1,20,000 insurance paid in December).", a: "Revenue nil, expense ₹1,20,000 — a ₹1,20,000 loss in the month all the work was done. February then shows a ₹4,00,000 profit for a month of no work." }, { q: "Name one genuine advantage and one genuine weakness of the cash basis.", a: "Advantage: simplicity, and it matches the bank statement exactly. Weakness: reported results follow payment dates, not activity, so periods can be badly misstated." }, { q: "Why can you not directly compare a cash-basis sole trader's 'profit' with a listed company's net profit?", a: "They measure different things: one is net cash movement, the other accrual earnings. The comparison mixes two definitions of the same word." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Cash accounting is simpler and matches the bank statement.<br>• It can seriously misstate which period the activity belonged to.<br>• Published company accounts are almost always on the accrual basis." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Comparing a cash-basis result with an accrual-basis result as if they were the same measure.<br><br>Assuming cash accounting is more truthful because it is simpler." },
      { t: "where", h: "Eligibility to use the cash basis, and any turnover thresholds, are set by local tax and accounting rules and change over time. Check the rules in force in your jurisdiction." },
      { t: "mcq", q: "Under cash accounting, revenue is recorded when…", opts: ["Goods are delivered", "Payment is received", "The order is placed", "The year ends"], correct: 1, why: ["Not this one. Money in is revenue on arrival; money out is expense on departure. Nothing else exists — no receivables, payables or prepayments.", "Correct. Money in is revenue on arrival; money out is expense on departure. Nothing else exists — no receivables, payables or prepayments.", "Not this one. Money in is revenue on arrival; money out is expense on departure. Nothing else exists — no receivables, payables or prepayments.", "Not this one. Money in is revenue on arrival; money out is expense on departure. Nothing else exists — no receivables, payables or prepayments."] },
      { t: "mcq", q: "Cash accounting can misstate a period because…", opts: ["It uses estimates heavily", "Payment dates, not activity, drive the numbers", "It requires complex judgement", "It double-counts revenue"], correct: 1, why: ["Not this one. A month of hard work paid late looks like a loss; a lazy month collecting old invoices looks brilliant.", "Correct. A month of hard work paid late looks like a loss; a lazy month collecting old invoices looks brilliant.", "Not this one. A month of hard work paid late looks like a loss; a lazy month collecting old invoices looks brilliant.", "Not this one. A month of hard work paid late looks like a loss; a lazy month collecting old invoices looks brilliant."] },
      { t: "mcq", q: "Published accounts of listed companies are almost always prepared on…", opts: ["The cash basis", "The accrual basis", "A hybrid chosen yearly", "No fixed basis"], correct: 1, why: ["Not this one. Accounting standards require accrual accounting for general-purpose financial statements.", "Correct. Accounting standards require accrual accounting for general-purpose financial statements.", "Not this one. Accounting standards require accrual accounting for general-purpose financial statements.", "Not this one. Accounting standards require accrual accounting for general-purpose financial statements."] }
    ]
  };

  LS.lessons["c-revenue-recognition"] = {
    id: "c-revenue-recognition", minutes: 5,
    title: "Revenue recognition",
    short: "Revenue recognition",
    desc: "The rules deciding when a sale can be recorded as revenue.",
    lede: "Revenue recognition answers a deceptively hard question: at what moment has the business actually earned the money? Signing a contract is not enough.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Revenue recognition answers a deceptively hard question: at what moment has the business actually earned the money? Signing a contract is not enough. Receiving cash is not enough. The general principle in modern accounting standards is that revenue is recorded when the business has done what it promised — when control of the goods or services has passed to the customer." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Revenue is the top line, so how it is recognised affects every profit figure below it. It is also the area where aggressive accounting most often appears, because pulling future revenue into the current period is a tempting way to flatter results." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Identify what the business has promised the customer.<br><br>2. Determine when control of that promise transfers — often on delivery.<br><br>3. If several promises exist in one contract, split the price between them and recognise each as it is delivered.<br><br>4. Cash received before delivery is recorded as deferred revenue, a liability." },
      { t: "example", h: "<p>A software firm sells a 12-month subscription for ₹1,20,000, collected upfront on 1 January.</p><ol><li>1 January: cash increases ₹1,20,000. Deferred revenue liability increases ₹1,20,000. Revenue recorded: nil.</li><li>Each month, one month of service is delivered: ₹10,000 moves from deferred revenue into revenue.</li><li>By 30 June, ₹60,000 has been recognised and ₹60,000 remains as a liability.</li></ol><p><strong>What it means.</strong> The firm holds all the cash from day one but has earned only part of it. The deferred revenue balance is a real obligation: if it stopped providing the service, it would owe the unearned portion back.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Performance obligation", h: "A distinct promise made to the customer in a contract." },
      { t: "def", term: "Transfer of control", h: "The point at which the customer obtains the benefit of what was promised." },
      { t: "def", term: "Deferred revenue", h: "Cash received for something not yet delivered — a liability." },
      { t: "def", term: "Unbilled revenue", h: "Revenue earned but not yet invoiced." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A software firm collects ₹1,20,000 on 1 January for a 12-month subscription. Show the position at 1 January and at 30 June.", a: "1 Jan: cash +1,20,000, deferred revenue 1,20,000, revenue nil. 30 Jun: revenue recognised ₹60,000 (6 × ₹10,000); deferred revenue ₹60,000 remains." }, { q: "A contract bundles a ₹80,000 machine (delivered day one) with ₹40,000 of two-year servicing. How is ₹1,20,000 of revenue recognised?", a: "Split by obligation: ₹80,000 on delivery of the machine; ₹40,000 spread over 24 months of service ≈ ₹1,667/month." }, { q: "A sales team books full contract value as revenue on signature. What does this do to current-period profit, and to future periods?", a: "It pulls future revenue forward, inflating today's profit and hollowing out later periods — the classic shape of aggressive recognition." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "deferred-revenue", title: "Subscription sandbox", prompt: "Slide months delivered from 0 to 12 and watch cash held turn into revenue earned.", fields: [{ key: "contractValue", label: "Collected upfront", value: 120000, unit: "₹" }, { key: "monthsTotal", label: "Months in contract", value: 12 }, { key: "monthsDelivered", label: "Months delivered", value: 6 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Revenue is recorded on delivery of the promise, not on signature or on payment.<br>• Cash received in advance is a liability until earned.<br>• Recognition timing is a common site of aggressive accounting — worth checking." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Recording the full contract value as revenue on signing.<br><br>Treating a customer deposit as revenue.<br><br>Ignoring multiple deliverables bundled into one price." },
      { t: "where", h: "Specific recognition criteria come from accounting standards (such as IFRS 15 or Ind AS 115) which are amended over time. The principle above is durable; the detailed rules are not." },
      { t: "mcq", q: "The general trigger for recognising revenue is…", opts: ["Signing the contract", "Receiving cash", "Transferring control of the promised goods or services", "Issuing the invoice"], correct: 2, why: ["Not this one. Neither signatures nor cash mean the business has performed. Delivery of the promise does.", "Not this one. Neither signatures nor cash mean the business has performed. Delivery of the promise does.", "Correct. Neither signatures nor cash mean the business has performed. Delivery of the promise does.", "Not this one. Neither signatures nor cash mean the business has performed. Delivery of the promise does."] },
      { t: "mcq", q: "A gym collects a ₹24,000 annual fee upfront. After 3 months it has earned…", opts: ["₹24,000", "₹6,000", "₹18,000", "Nothing until year-end"], correct: 1, why: ["Not this one. 3/12 × 24,000 = ₹6,000 recognised; ₹18,000 remains a liability owed in service.", "Correct. 3/12 × 24,000 = ₹6,000 recognised; ₹18,000 remains a liability owed in service.", "Not this one. 3/12 × 24,000 = ₹6,000 recognised; ₹18,000 remains a liability owed in service.", "Not this one. 3/12 × 24,000 = ₹6,000 recognised; ₹18,000 remains a liability owed in service."] },
      { t: "mcq", q: "Deferred revenue would have to be repaid if…", opts: ["Profits fall", "The service is never delivered", "The customer complains", "Interest rates rise"], correct: 1, why: ["Not this one. It is a real obligation: money held for performance not yet rendered.", "Correct. It is a real obligation: money held for performance not yet rendered.", "Not this one. It is a real obligation: money held for performance not yet rendered.", "Not this one. It is a real obligation: money held for performance not yet rendered."] }
    ]
  };

  LS.lessons["c-expenses"] = {
    id: "c-expenses", minutes: 5,
    title: "Expenses",
    short: "Expenses",
    desc: "Costs recorded against the period they belong to, whether or not they have been paid.",
    lede: "An expense is a cost recognised in the income statement for a particular period.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "An expense is a cost recognised in the income statement for a particular period. The key idea is matching: a cost belongs to the period whose revenue it helped produce, or to the period it simply relates to. Paying for something and expensing it are separate events that often happen at different times." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Which period a cost lands in determines reported profit. Understanding the difference between paying, expensing and capitalising is what lets you tell a genuinely profitable year from a well-timed one." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. If a cost is consumed now, expense it now.<br><br>2. If it is paid now but consumed later, hold it as a prepaid asset and expense it as it is used.<br><br>3. If it is consumed now but paid later, record the expense now and an accrued liability alongside it.<br><br>4. If it buys a benefit lasting several years, capitalise it as an asset and expense a portion each year." },
      { t: "example", h: "<p>Four December costs at a firm with a December year-end.</p><ol><li>₹50,000 of electricity used in December, invoice arriving in January: expense ₹50,000 in December, with a ₹50,000 accrued liability.</li><li>₹60,000 paid in December for January–March office cleaning: no December expense; ₹60,000 prepaid asset.</li><li>₹80,000 of salaries for December work, paid in December: expense ₹80,000.</li><li>₹6,00,000 for a delivery van expected to last 5 years: not an expense. Record a ₹6,00,000 asset and expense ₹1,20,000 a year.</li></ol><p><strong>What it means.</strong> December cash out was ₹1,40,000 + ₹6,00,000 = ₹7,40,000, but December expense was ₹1,30,000 + ₹1,20,000 depreciation. Paying and expensing are genuinely different events.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Accrued expense", h: "A cost incurred but not yet invoiced or paid." },
      { t: "def", term: "Prepaid expense", h: "A cost paid in advance of the benefit being received." },
      { t: "def", term: "Capitalise", h: "Record a cost as an asset because its benefit lasts beyond the current period." },
      { t: "def", term: "Matching principle", h: "Recording costs in the same period as the revenue they support." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "December events: ₹50,000 electricity used (billed January); ₹60,000 paid for Jan–Mar cleaning; ₹80,000 December salaries paid; a ₹6,00,000 van bought (5-year life). Compute December's expense.", a: "Electricity 50,000 (accrued) + salaries 80,000 + van depreciation 6,00,000÷5÷12 = 10,000 → ₹1,40,000. The cleaning is prepaid; the van is capitalised." }, { q: "December's cash outflow for the same events?", a: "60,000 + 80,000 + 6,00,000 = ₹7,40,000. Expense ₹1.4L vs cash ₹7.4L — paying and expensing are different events." }, { q: "A firm capitalises routine repairs as assets. What does this do to this year's profit, and why is it misleading?", a: "Profit is flattered because a current cost is parked on the balance sheet and expensed slowly. Repairs have no multi-year benefit, so the treatment misstates performance." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "spread-cost", title: "Prepaid spreading sandbox", prompt: "Pay once, expense monthly. Watch the prepaid asset drain to zero as months elapse.", fields: [{ key: "totalCost", label: "Paid upfront", value: 240000, unit: "₹" }, { key: "monthsCovered", label: "Months covered", value: 12 }, { key: "monthsElapsed", label: "Months elapsed", value: 3 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Expense recognition follows consumption, not payment.<br>• Costs with multi-year benefits are capitalised and expensed gradually.<br>• The gap between cash paid and expense recorded explains much of the profit-versus-cash difference." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Expensing everything on payment.<br><br>Capitalising costs that should be expensed, which flatters current profit.<br><br>Forgetting to accrue for costs incurred but not yet invoiced." },
      { t: "mcq", q: "A cost paid now but consumed next year is recorded now as…", opts: ["An expense", "A prepaid asset", "A liability", "Revenue"], correct: 1, why: ["Not this one. The benefit is still owed to you; it becomes expense as it is consumed.", "Correct. The benefit is still owed to you; it becomes expense as it is consumed.", "Not this one. The benefit is still owed to you; it becomes expense as it is consumed.", "Not this one. The benefit is still owed to you; it becomes expense as it is consumed."] },
      { t: "mcq", q: "A cost consumed now but invoiced next month is…", opts: ["Ignored until the invoice", "Expensed now, with an accrued liability", "Capitalised", "Netted against revenue"], correct: 1, why: ["Not this one. Matching puts the cost in the period it was incurred; the accrual records the amount owed.", "Correct. Matching puts the cost in the period it was incurred; the accrual records the amount owed.", "Not this one. Matching puts the cost in the period it was incurred; the accrual records the amount owed.", "Not this one. Matching puts the cost in the period it was incurred; the accrual records the amount owed."] },
      { t: "mcq", q: "A ₹6,00,000 van with a 5-year life is bought. This year's expense from the purchase is…", opts: ["₹6,00,000", "₹1,20,000", "₹0 forever", "₹3,00,000"], correct: 1, why: ["Not this one. Capitalise, then depreciate: 6,00,000 ÷ 5 = ₹1,20,000 per year.", "Correct. Capitalise, then depreciate: 6,00,000 ÷ 5 = ₹1,20,000 per year.", "Not this one. Capitalise, then depreciate: 6,00,000 ÷ 5 = ₹1,20,000 per year.", "Not this one. Capitalise, then depreciate: 6,00,000 ÷ 5 = ₹1,20,000 per year."] }
    ]
  };

  LS.lessons["c-accounts-receivable"] = {
    id: "c-accounts-receivable", minutes: 5,
    title: "Accounts receivable",
    short: "Accounts receivable",
    desc: "Money customers owe you for goods or services already delivered.",
    lede: "When you deliver first and get paid later, the amount owed to you is a receivable.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "When you deliver first and get paid later, the amount owed to you is a receivable. It is an asset because you expect cash from it, but it is not cash — and it only becomes cash if the customer actually pays. Every rupee of receivables is a rupee of your money currently financing your customer." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Receivables are the most common reason a profitable business runs short of cash. Revenue can grow beautifully while collections lag, and the gap has to be funded from somewhere." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. A sale on credit creates revenue and a receivable at the same moment.<br><br>2. When the customer pays, the receivable turns into cash. No new revenue is recorded.<br><br>3. If a customer will not pay, the receivable must be written down — reducing profit.<br><br>4. Days sales outstanding (DSO) measures how long collection takes on average." },
      { t: "formula", title: "Average number of days it takes to collect from customers", lines: ["<b>DSO = (Receivables ÷ Revenue) × 365</b>", "Receivables = Amount owed by customers at the period end", "Revenue = Sales for the period, usually a full year"] },
      { t: "example", h: "<p>A business has annual revenue of ₹36,50,000 and year-end receivables of ₹6,00,000.</p><ol><li>DSO = (₹6,00,000 ÷ ₹36,50,000) × 365 = 60 days.</li><li>The following year revenue grows to ₹50,00,000 but DSO slips to 90 days.</li><li>New receivables = (90 ÷ 365) × ₹50,00,000 = ₹12,32,877.</li><li>Cash tied up rose by ₹12,32,877 − ₹6,00,000 = ₹6,32,877.</li></ol><p><strong>What it means.</strong> Revenue grew 37% and the business had to find an extra ₹6.3 lakh just to fund unpaid invoices. Growth consumed cash before it produced any.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Receivable", h: "Money owed by a customer for goods or services already delivered." },
      { t: "def", term: "DSO", h: "Days sales outstanding — average days taken to collect." },
      { t: "def", term: "Bad debt", h: "A receivable that will not be collected." },
      { t: "def", term: "Ageing", h: "A breakdown of receivables by how overdue they are." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Annual revenue ₹36,50,000; year-end receivables ₹6,00,000. Compute DSO.", a: "(6,00,000 ÷ 36,50,000) × 365 = 60 days." }, { q: "Next year revenue is ₹50,00,000 and DSO slips to 90 days. How much extra cash is tied up in receivables?", a: "New receivables = 90/365 × 50,00,000 = ₹12,32,877; increase ≈ ₹6,32,877 that must be funded." }, { q: "A customer owing ₹3,00,000 goes bankrupt. Trace the effect through the statements.", a: "The receivable is written off: assets fall ₹3,00,000 and a bad-debt expense cuts profit by the same. No cash moves — the cash never arrived." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "receivables-cash", title: "Collection speed sandbox", prompt: "Move DSO from 60 to 90 days and see how much cash growth quietly demands.", fields: [{ key: "revenue", label: "Annual revenue", value: 5000000, unit: "₹" }, { key: "dsoNow", label: "Current DSO", value: 60, unit: "days" }, { key: "dsoNew", label: "New DSO", value: 90, unit: "days" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "A receivable is revenue already recognised but cash not yet received.<br>• Rising receivables consume cash, and growth makes this worse.<br>• Rising DSO alongside rising revenue is a warning worth investigating." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Counting receivables as cash when assessing liquidity.<br><br>Watching only the receivables total instead of its size relative to revenue." },
      { t: "mcq", q: "A receivable represents…", opts: ["Cash in the bank", "Revenue recognised but not yet collected", "A supplier debt", "Future orders"], correct: 1, why: ["Not this one. Delivery happened, payment has not — your money is financing the customer meanwhile.", "Correct. Delivery happened, payment has not — your money is financing the customer meanwhile.", "Not this one. Delivery happened, payment has not — your money is financing the customer meanwhile.", "Not this one. Delivery happened, payment has not — your money is financing the customer meanwhile."] },
      { t: "mcq", q: "Receivables ₹8,00,000 against annual revenue ₹48,66,667. DSO is about…", opts: ["30 days", "60 days", "90 days", "120 days"], correct: 1, why: ["Not this one. (8,00,000 ÷ 48,66,667) × 365 ≈ 60 days.", "Correct. (8,00,000 ÷ 48,66,667) × 365 ≈ 60 days.", "Not this one. (8,00,000 ÷ 48,66,667) × 365 ≈ 60 days.", "Not this one. (8,00,000 ÷ 48,66,667) × 365 ≈ 60 days."] },
      { t: "mcq", q: "Revenue rising while DSO also rises suggests…", opts: ["Improving cash collection", "Growth partly bought with looser credit terms — worth investigating", "Falling sales", "Nothing at all"], correct: 1, why: ["Not this one. Extending credit inflates sales today and cash risk tomorrow. The combination is a standard red flag.", "Correct. Extending credit inflates sales today and cash risk tomorrow. The combination is a standard red flag.", "Not this one. Extending credit inflates sales today and cash risk tomorrow. The combination is a standard red flag.", "Not this one. Extending credit inflates sales today and cash risk tomorrow. The combination is a standard red flag."] }
    ]
  };

  LS.lessons["c-accounts-payable"] = {
    id: "c-accounts-payable", minutes: 5,
    title: "Accounts payable",
    short: "Accounts payable",
    desc: "Money you owe suppliers for goods or services you have already received.",
    lede: "Payables are the mirror image of receivables.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Payables are the mirror image of receivables. You have taken delivery but not yet paid, so you owe the supplier. It is a liability — and, usefully, a source of free short-term funding, because most suppliers do not charge interest for standard credit terms." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Payables are how a business funds part of its operations without borrowing. Stretching them too far damages supplier relationships and can signal cash trouble; paying too quickly wastes free financing." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Receiving goods on credit creates both an expense or asset and a payable.<br><br>2. Paying the supplier reduces cash and reduces the payable. No new expense arises.<br><br>3. An increase in payables over a period is a source of cash.<br><br>4. Days payable outstanding (DPO) measures how long the business takes to pay." },
      { t: "formula", title: "Average number of days taken to pay suppliers", lines: ["<b>DPO = (Payables ÷ Cost of goods sold) × 365</b>", "Payables = Amount owed to suppliers at the period end", "Cost of goods sold = Direct cost of what was sold during the period"] },
      { t: "example", h: "<p>A retailer has annual cost of goods sold of ₹73,00,000 and payables of ₹12,00,000.</p><ol><li>DPO = (₹12,00,000 ÷ ₹73,00,000) × 365 = 60 days.</li><li>It negotiates 75-day terms. New payables = (75 ÷ 365) × ₹73,00,000 = ₹15,00,000.</li><li>Cash released = ₹15,00,000 − ₹12,00,000 = ₹3,00,000.</li></ol><p><strong>What it means.</strong> The extra 15 days of credit freed ₹3 lakh of cash permanently, with no borrowing. This is a genuine one-off benefit — but it happens once, and it does not repeat next year.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Payable", h: "Money owed to a supplier for goods or services already received." },
      { t: "def", term: "DPO", h: "Days payable outstanding — average days taken to pay suppliers." },
      { t: "def", term: "Trade credit", h: "The credit period a supplier allows before payment is due." },
      { t: "def", term: "Early-payment discount", h: "A reduction offered for paying sooner than the standard terms." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Annual COGS ₹73,00,000; payables ₹12,00,000. Compute DPO.", a: "(12,00,000 ÷ 73,00,000) × 365 = 60 days." }, { q: "Terms improve to 75 days. How much one-off cash is released?", a: "New payables = 75/365 × 73,00,000 = ₹15,00,000 → ₹3,00,000 released. It does not repeat next year." }, { q: "A supplier offers 2% off for paying in 10 days instead of 40. Roughly what annual rate do you 'earn' by paying early?", a: "2% for giving up 30 days ≈ 2% × 365/30 ≈ 24% annualised. Skipping the discount is expensive borrowing." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "payables-cash", title: "Supplier credit sandbox", prompt: "Stretch DPO and see the cash released — then remember it happens exactly once.", fields: [{ key: "cogs", label: "Annual cost of goods", value: 7300000, unit: "₹" }, { key: "dpoNow", label: "Current DPO", value: 60, unit: "days" }, { key: "dpoNew", label: "New DPO", value: 75, unit: "days" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Payables are interest-free short-term funding from suppliers.<br>• Increasing payables releases cash; the benefit is one-off, not recurring.<br>• Sharply rising DPO can indicate deliberate strategy or genuine cash difficulty." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Treating a payables increase as a permanent improvement in cash generation.<br><br>Ignoring the cost of a forgone early-payment discount, which can be an expensive form of credit." },
      { t: "mcq", q: "Accounts payable is…", opts: ["Money customers owe you", "Money you owe suppliers for goods already received", "A bank loan", "An expense account"], correct: 1, why: ["Not this one. The mirror of receivables: delivery received, payment pending — free short-term funding meanwhile.", "Correct. The mirror of receivables: delivery received, payment pending — free short-term funding meanwhile.", "Not this one. The mirror of receivables: delivery received, payment pending — free short-term funding meanwhile.", "Not this one. The mirror of receivables: delivery received, payment pending — free short-term funding meanwhile."] },
      { t: "mcq", q: "An increase in payables over a period is…", opts: ["A use of cash", "A source of cash", "Cash-neutral", "Always a bad sign"], correct: 1, why: ["Not this one. Holding suppliers' money longer means cash stays with you — a one-off release, not recurring flow.", "Correct. Holding suppliers' money longer means cash stays with you — a one-off release, not recurring flow.", "Not this one. Holding suppliers' money longer means cash stays with you — a one-off release, not recurring flow.", "Not this one. Holding suppliers' money longer means cash stays with you — a one-off release, not recurring flow."] },
      { t: "mcq", q: "A sharply rising DPO can mean…", opts: ["Only deliberate strategy", "Only distress", "Either negotiated terms or genuine cash trouble — context decides", "Nothing"], correct: 2, why: ["Not this one. The number alone is ambiguous; supplier relationships and liquidity elsewhere tell you which story it is.", "Not this one. The number alone is ambiguous; supplier relationships and liquidity elsewhere tell you which story it is.", "Correct. The number alone is ambiguous; supplier relationships and liquidity elsewhere tell you which story it is.", "Not this one. The number alone is ambiguous; supplier relationships and liquidity elsewhere tell you which story it is."] }
    ]
  };

  LS.lessons["c-inventory"] = {
    id: "c-inventory", minutes: 5,
    title: "Inventory",
    short: "Inventory",
    desc: "Goods held for sale, and the cash sitting inside them until they sell.",
    lede: "Inventory is what a business holds to sell: raw materials, part-finished goods and finished products.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Inventory is what a business holds to sell: raw materials, part-finished goods and finished products. It is an asset, but a peculiar one — it is cash you have already spent that only returns when someone buys. Until then it takes up space, risks going out of date, and earns nothing." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Inventory is often the largest single consumer of cash in a product business. It also sits at the centre of the difference between profit and cash, because buying stock uses cash without creating any expense." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Buying stock converts cash into inventory. No expense is recorded.<br><br>2. When an item sells, its cost moves from inventory into cost of goods sold, becoming an expense.<br><br>3. Unsold or obsolete stock must be written down, which reduces profit.<br><br>4. Days inventory outstanding (DIO) measures how long stock sits before selling." },
      { t: "formula", title: "Average number of days inventory is held before being sold", lines: ["<b>DIO = (Inventory ÷ Cost of goods sold) × 365</b>", "Inventory = Value of stock held at the period end", "Cost of goods sold = Direct cost of goods sold during the period"] },
      { t: "example", h: "<p>A clothing retailer buys ₹10,00,000 of stock in March and sells three-quarters of it by June for ₹18,00,000.</p><ol><li>March: cash −₹10,00,000, inventory +₹10,00,000. Profit effect: nil.</li><li>By June, cost of the sold portion = ₹10,00,000 × 75% = ₹7,50,000.</li><li>Gross profit = ₹18,00,000 − ₹7,50,000 = ₹10,50,000.</li><li>₹2,50,000 of stock remains. If the season ends and it must be cleared at half price, ₹1,25,000 is written off against profit.</li></ol><p><strong>What it means.</strong> The March purchase hit cash immediately but profit not at all. The unsold quarter is a risk sitting on the balance sheet — inventory is only worth its recorded value if someone eventually buys it at that price.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Cost of goods sold", h: "The cost of the inventory that was actually sold in the period." },
      { t: "def", term: "DIO", h: "Days inventory outstanding — average days stock is held." },
      { t: "def", term: "Write-down", h: "Reducing inventory's recorded value when it cannot be sold at that price." },
      { t: "def", term: "Obsolescence", h: "Stock losing value because it is out of date or unwanted." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A retailer buys ₹10,00,000 of stock in March. What are the profit and cash effects that month?", a: "Cash −₹10,00,000; profit unchanged. Buying stock converts one asset into another — the cost waits in inventory." }, { q: "By June, 75% has sold for ₹18,00,000. Compute COGS and gross profit.", a: "COGS = 75% × 10,00,000 = ₹7,50,000; gross profit = 18,00,000 − 7,50,000 = ₹10,50,000." }, { q: "Season ends; the remaining ₹2,50,000 of stock must clear at half price. Effect on profit?", a: "A write-down of ₹1,25,000 hits profit now. Inventory is only worth book value if someone will pay it." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "sell-through", title: "Stock sandbox", prompt: "Lower the percentage sold and watch profit hold while cash stays trapped on the shelf.", fields: [{ key: "stockBought", label: "Stock purchased", value: 1000000, unit: "₹" }, { key: "percentSold", label: "Sold by period end", value: 75, unit: "%" }, { key: "markup", label: "Markup on cost", value: 140, unit: "%" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Buying inventory consumes cash without creating an expense.<br>• Cost becomes an expense only when the item sells.<br>• Rising inventory alongside flat sales is one of the clearest early warning signs in a product business." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Assuming inventory is worth its balance-sheet value regardless of demand.<br><br>Overlooking that stockpiling drains cash while leaving reported profit untouched." },
      { t: "mcq", q: "Buying inventory with cash…", opts: ["Creates an expense immediately", "Reduces cash with no profit effect", "Increases profit", "Creates a liability"], correct: 1, why: ["Not this one. Cost sits in the inventory asset until the item sells; only then does it become cost of goods sold.", "Correct. Cost sits in the inventory asset until the item sells; only then does it become cost of goods sold.", "Not this one. Cost sits in the inventory asset until the item sells; only then does it become cost of goods sold.", "Not this one. Cost sits in the inventory asset until the item sells; only then does it become cost of goods sold."] },
      { t: "mcq", q: "Inventory ₹15,00,000; annual COGS ₹73,00,000. Days inventory outstanding is about…", opts: ["25 days", "50 days", "75 days", "100 days"], correct: 2, why: ["Not this one. (15,00,000 ÷ 73,00,000) × 365 ≈ 75 days on the shelf before selling.", "Not this one. (15,00,000 ÷ 73,00,000) × 365 ≈ 75 days on the shelf before selling.", "Correct. (15,00,000 ÷ 73,00,000) × 365 ≈ 75 days on the shelf before selling.", "Not this one. (15,00,000 ÷ 73,00,000) × 365 ≈ 75 days on the shelf before selling."] },
      { t: "mcq", q: "Inventory climbing while sales stay flat usually signals…", opts: ["Efficient buying", "Demand falling short of purchases — discounting or write-downs ahead", "Strong pricing power", "Better margins"], correct: 1, why: ["Not this one. Stock piling up unsold is one of the earliest visible warnings in a product business.", "Correct. Stock piling up unsold is one of the earliest visible warnings in a product business.", "Not this one. Stock piling up unsold is one of the earliest visible warnings in a product business.", "Not this one. Stock piling up unsold is one of the earliest visible warnings in a product business."] }
    ]
  };

  LS.lessons["c-prepaid-expenses"] = {
    id: "c-prepaid-expenses", minutes: 5,
    title: "Prepaid expenses",
    short: "Prepaid expenses",
    desc: "Costs paid in advance that have not yet been used up.",
    lede: "A prepaid expense is cash paid now for a benefit you will receive later — a year of insurance, rent paid in advance, an annual software licence.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "A prepaid expense is cash paid now for a benefit you will receive later — a year of insurance, rent paid in advance, an annual software licence. Because the benefit is still to come, it is an asset. It becomes an expense gradually, as the benefit is consumed." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Prepayments are a clear, small-scale illustration of accrual accounting. They also matter in forecasting: a prepayment is cash already gone, so future periods carry the expense without any further cash outflow." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Pay in advance: cash decreases, a prepaid asset increases. No expense yet.<br><br>2. Each period, transfer the portion consumed from the asset into expense.<br><br>3. By the end of the covered period, the asset has reduced to nil.<br><br>4. The cash outflow happened once; the expense is spread across the periods benefited." },
      { t: "example", h: "<p>On 1 April a business pays ₹2,40,000 for 12 months of insurance cover running April to March.</p><ol><li>1 April: cash −₹2,40,000, prepaid expenses +₹2,40,000. Expense recorded: nil.</li><li>Monthly expense = ₹2,40,000 ÷ 12 = ₹20,000.</li><li>At 30 June, three months consumed: expense to date ₹60,000, prepaid asset remaining ₹1,80,000.</li><li>At 31 March: expense ₹2,40,000 in total, prepaid asset nil.</li></ol><p><strong>What it means.</strong> Cash left in a single month, but the cost was borne across twelve. Judging April's performance by cash spent would have made a normal month look disastrous.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Prepaid expense", h: "Cash paid in advance for a benefit not yet received." },
      { t: "def", term: "Amortisation of prepayment", h: "Moving the consumed portion from asset to expense each period." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "₹2,40,000 paid on 1 April for 12 months of insurance. What sits on the balance sheet at 30 June, and how much expense has been recognised?", a: "Monthly ₹20,000. Expense to date ₹60,000; prepaid asset remaining ₹1,80,000." }, { q: "Why would judging April by its cash outflow misread the month?", a: "April shows ₹2,40,000 leaving for a benefit spread over a year. Expense of ₹20,000 is the fair monthly burden; cash timing exaggerates it twelvefold." }, { q: "The bookkeeper forgets to release the prepayment after June. What goes wrong in later months?", a: "Expenses are understated and profit overstated each month, while a stale asset lingers — until a correction lumps the error into one period." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "spread-cost", title: "Prepayment sandbox", prompt: "Advance the elapsed months and watch the asset convert into expense on schedule.", fields: [{ key: "totalCost", label: "Paid in advance", value: 240000, unit: "₹" }, { key: "monthsCovered", label: "Months of cover", value: 12 }, { key: "monthsElapsed", label: "Months used", value: 3 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "A prepayment is an asset because the benefit is still owed to you.<br>• Cash goes out once; the expense is recognised across the periods benefited.<br>• Future periods will carry expense with no matching cash outflow." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Expensing the whole payment in the month it is paid.<br><br>Forgetting to release the prepayment, so expense is understated in later periods." },
      { t: "mcq", q: "A prepaid expense is an asset because…", opts: ["It earns interest", "The benefit is still owed to the business", "It can be sold", "Accounting rules are arbitrary"], correct: 1, why: ["Not this one. You have paid; the counterparty still owes you cover, rent or service — a future benefit.", "Correct. You have paid; the counterparty still owes you cover, rent or service — a future benefit.", "Not this one. You have paid; the counterparty still owes you cover, rent or service — a future benefit.", "Not this one. You have paid; the counterparty still owes you cover, rent or service — a future benefit."] },
      { t: "mcq", q: "₹1,20,000 paid for a 12-month licence: the monthly expense is…", opts: ["₹1,20,000", "₹10,000", "₹12,000", "Nil"], correct: 1, why: ["Not this one. 1,20,000 ÷ 12 = ₹10,000 flows from asset to expense each month.", "Correct. 1,20,000 ÷ 12 = ₹10,000 flows from asset to expense each month.", "Not this one. 1,20,000 ÷ 12 = ₹10,000 flows from asset to expense each month.", "Not this one. 1,20,000 ÷ 12 = ₹10,000 flows from asset to expense each month."] },
      { t: "mcq", q: "After the covered period ends, the prepaid balance should be…", opts: ["Its original amount", "Zero", "Negative", "Reclassified as revenue"], correct: 1, why: ["Not this one. Fully consumed benefit means fully released asset.", "Correct. Fully consumed benefit means fully released asset.", "Not this one. Fully consumed benefit means fully released asset.", "Not this one. Fully consumed benefit means fully released asset."] }
    ]
  };

  LS.lessons["c-deferred-revenue"] = {
    id: "c-deferred-revenue", minutes: 5,
    title: "Deferred revenue",
    short: "Deferred revenue",
    desc: "Cash collected for something you have not yet delivered — a liability, not revenue.",
    lede: "Deferred revenue arises when a customer pays before you deliver.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Deferred revenue arises when a customer pays before you deliver. You hold their money but still owe them the goods or service, so it is a liability. It becomes revenue only as you deliver. Beginners find this counter-intuitive: money in the bank appearing as an obligation." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Deferred revenue is common in subscriptions, maintenance contracts and anything sold annually upfront. It funds the business at no interest cost, and a growing balance is often a genuinely positive sign — customers are committing ahead." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Cash received in advance: cash increases, deferred revenue liability increases. No revenue.<br><br>2. As delivery occurs, the liability decreases and revenue is recognised.<br><br>3. A growing deferred revenue balance means the business is collecting faster than it delivers.<br><br>4. The liability is real: undelivered service generally means the money is refundable." },
      { t: "example", h: "<p>A gym sells 500 annual memberships at ₹24,000 each on 1 January, all collected upfront.</p><ol><li>1 January: cash +₹1,20,00,000; deferred revenue +₹1,20,00,000. Revenue recognised: nil.</li><li>Monthly revenue as service is delivered = ₹1,20,00,000 ÷ 12 = ₹10,00,000.</li><li>At 30 June: revenue recognised ₹60,00,000; deferred revenue remaining ₹60,00,000.</li></ol><p><strong>What it means.</strong> In January the gym holds ₹1.2 crore of cash and has earned none of it. That cash funds six months of operations interest-free — but if it closed in June it would owe roughly ₹60 lakh back.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Deferred revenue", h: "Cash received for goods or services not yet delivered." },
      { t: "def", term: "Unearned revenue", h: "Another name for deferred revenue." },
      { t: "def", term: "Billings", h: "Amounts invoiced in a period, which may differ from revenue recognised." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A gym sells 500 annual memberships at ₹24,000 on 1 January, all cash upfront. State the 1 January position.", a: "Cash +₹1,20,00,000; deferred revenue liability ₹1,20,00,000; revenue nil — everything is still owed in service." }, { q: "Revenue recognised by 30 June, and the remaining obligation?", a: "₹10,00,000/month × 6 = ₹60,00,000 recognised; ₹60,00,000 still deferred." }, { q: "Why can a growing deferred-revenue balance be good news?", a: "It means customers are paying ahead faster than service is delivered — commitment plus interest-free funding. The liability label describes mechanics, not distress." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "deferred-revenue", title: "Advance collections sandbox", prompt: "Watch the liability shrink month by month as delivery converts it into revenue.", fields: [{ key: "contractValue", label: "Cash collected upfront", value: 12000000, unit: "₹" }, { key: "monthsTotal", label: "Service period (months)", value: 12 }, { key: "monthsDelivered", label: "Months delivered", value: 6 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Cash received before delivery is a liability, not revenue.<br>• It provides interest-free funding and often signals customer commitment.<br>• Revenue and cash collection can diverge dramatically in subscription businesses." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Recording upfront collections as immediate revenue.<br><br>Reading a rising deferred revenue balance as a problem — it usually indicates growth." },
      { t: "mcq", q: "Cash collected before delivery appears as…", opts: ["Revenue", "Deferred revenue, a liability", "Equity", "A receivable"], correct: 1, why: ["Not this one. Until performance happens, the business owes the customer — money held is not money earned.", "Correct. Until performance happens, the business owes the customer — money held is not money earned.", "Not this one. Until performance happens, the business owes the customer — money held is not money earned.", "Not this one. Until performance happens, the business owes the customer — money held is not money earned."] },
      { t: "mcq", q: "A ₹36,000 three-year service plan collected upfront recognises per year…", opts: ["₹36,000", "₹12,000", "₹18,000", "Nothing"], correct: 1, why: ["Not this one. Delivery is even across three years: ₹12,000 of the liability converts to revenue annually.", "Correct. Delivery is even across three years: ₹12,000 of the liability converts to revenue annually.", "Not this one. Delivery is even across three years: ₹12,000 of the liability converts to revenue annually.", "Not this one. Delivery is even across three years: ₹12,000 of the liability converts to revenue annually."] },
      { t: "mcq", q: "If the provider shut down halfway through prepaid contracts, deferred revenue balances would…", opts: ["Become profit", "Generally be refundable to customers", "Convert to equity", "Vanish"], correct: 1, why: ["Not this one. The balance measures undelivered obligation — which is why it is a liability in the first place.", "Correct. The balance measures undelivered obligation — which is why it is a liability in the first place.", "Not this one. The balance measures undelivered obligation — which is why it is a liability in the first place.", "Not this one. The balance measures undelivered obligation — which is why it is a liability in the first place."] }
    ]
  };

  LS.lessons["c-accrued-expenses"] = {
    id: "c-accrued-expenses", minutes: 5,
    title: "Accrued expenses",
    short: "Accrued expenses",
    desc: "Costs you have already incurred but not yet been billed for or paid.",
    lede: "An accrued expense is a cost the business has already used but has not yet paid or even received an invoice for — electricity consumed this month, salaries earned but paid next month, interest that has built up since the last payment date.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "An accrued expense is a cost the business has already used but has not yet paid or even received an invoice for — electricity consumed this month, salaries earned but paid next month, interest that has built up since the last payment date. Accrual accounting requires recording it now, along with the liability." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Without accruals, a period's costs would be understated simply because invoices arrived late. Accruals are also where estimates enter the accounts, so they are worth understanding as a place where judgement is applied." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Identify costs consumed in the period but not yet invoiced or paid.<br><br>2. Record the expense now and an accrued liability of the same amount.<br><br>3. When the invoice is paid, cash and the liability both reduce. No new expense arises.<br><br>4. Where the exact amount is unknown, a reasonable estimate is used and corrected later." },
      { t: "example", h: "<p>A company's year ends 31 March. Staff earned ₹15,00,000 in March, paid on 5 April. Electricity used in March, billed ₹2,40,000 in April.</p><ol><li>31 March: record ₹15,00,000 salary expense and a ₹15,00,000 accrued liability.</li><li>31 March: record ₹2,40,000 electricity expense and a ₹2,40,000 accrued liability.</li><li>March profit is reduced by ₹17,40,000 even though no cash moved in March.</li><li>April: paying both reduces cash and the liabilities by ₹17,40,000. April expense: nil.</li></ol><p><strong>What it means.</strong> Without these accruals, March would have shown ₹17.4 lakh more profit than it earned, and April would have absorbed costs belonging to March.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Accrued expense", h: "A cost incurred but not yet invoiced or paid." },
      { t: "def", term: "Accrued liability", h: "The balance sheet obligation created by an accrued expense." },
      { t: "def", term: "Reversal", h: "Removing an accrual once the actual invoice is recorded." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Year-end 31 March: staff earned ₹15,00,000 in March (paid 5 April); March electricity of ₹2,40,000 billed in April. Record the year-end accruals and their profit effect.", a: "Accrue both: expenses +₹17,40,000 and accrued liabilities +₹17,40,000. March profit falls ₹17.4 lakh though no cash moved." }, { q: "In April both are paid. What happens in April's accounts?", a: "Cash −₹17,40,000 and liabilities −₹17,40,000. No April expense — the cost already belonged to March." }, { q: "How do accrued expenses differ from accounts payable?", a: "Payables rest on received invoices; accruals record costs incurred before any invoice exists, so they usually involve estimation." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Accruals record costs in the period they were incurred, regardless of invoicing.<br>• They create a liability that is settled later with no further expense.<br>• They involve estimates, making them a normal point of judgement in accounts." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Waiting for an invoice before recording a cost.<br><br>Double-counting by recording both the accrual and the invoice as expenses." },
      { t: "mcq", q: "An accrued expense is…", opts: ["A cost paid in advance", "A cost incurred but not yet invoiced or paid", "A bad debt", "A capitalised cost"], correct: 1, why: ["Not this one. Consumption came first; the paperwork and payment follow later.", "Correct. Consumption came first; the paperwork and payment follow later.", "Not this one. Consumption came first; the paperwork and payment follow later.", "Not this one. Consumption came first; the paperwork and payment follow later."] },
      { t: "mcq", q: "Failing to accrue March's ₹2,40,000 electricity bill would…", opts: ["Understate March profit", "Overstate March profit by ₹2,40,000", "Have no effect", "Reduce cash"], correct: 1, why: ["Not this one. A cost belonging to March would be missing from March — profit looks better than it was.", "Correct. A cost belonging to March would be missing from March — profit looks better than it was.", "Not this one. A cost belonging to March would be missing from March — profit looks better than it was.", "Not this one. A cost belonging to March would be missing from March — profit looks better than it was."] },
      { t: "mcq", q: "When the accrued invoice is finally paid…", opts: ["A second expense is recorded", "Cash and the liability both fall, with no new expense", "Revenue rises", "Equity rises"], correct: 1, why: ["Not this one. The expense already happened at accrual; payment merely settles the obligation.", "Correct. The expense already happened at accrual; payment merely settles the obligation.", "Not this one. The expense already happened at accrual; payment merely settles the obligation.", "Not this one. The expense already happened at accrual; payment merely settles the obligation."] }
    ]
  };

  LS.lessons["c-working-capital"] = {
    id: "c-working-capital", minutes: 5,
    title: "Working capital",
    short: "Working capital",
    desc: "The cash tied up in day-to-day operations: stock and unpaid invoices, less supplier credit.",
    lede: "Working capital is the money locked into running the business day to day.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Working capital is the money locked into running the business day to day. You have cash sitting in inventory and in invoices customers have not paid, offset by invoices you have not paid your suppliers. The net figure is the amount your business must fund out of its own resources simply to operate." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Working capital is where the profit-versus-cash gap becomes concrete. A growing business needs more stock and carries more unpaid invoices, so growth itself absorbs cash. This is the mechanism behind most cash crises at otherwise healthy companies." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Add operating current assets: mainly inventory and receivables.<br><br>2. Subtract operating current liabilities: mainly payables and accrued expenses.<br><br>3. The result is what the business must finance itself.<br><br>4. An increase in working capital consumes cash; a decrease releases it." },
      { t: "formula", title: "Cash tied up in day-to-day operations", lines: ["<b>Operating working capital = Inventory + Receivables − Payables</b>", "Inventory = Stock held for sale", "Receivables = Amounts owed by customers", "Payables = Amounts owed to suppliers"] },
      { t: "example", h: "<p>A distributor's balances at the start and end of a year in which revenue grew 40%.</p><ol><li>Start: inventory ₹20,00,000 + receivables ₹15,00,000 − payables ₹12,00,000 = ₹23,00,000.</li><li>End: inventory ₹28,00,000 + receivables ₹21,00,000 − payables ₹16,00,000 = ₹33,00,000.</li><li>Increase in working capital = ₹33,00,000 − ₹23,00,000 = ₹10,00,000.</li></ol><p><strong>What it means.</strong> Growth absorbed ₹10 lakh of cash. If the year's profit was ₹8 lakh, the business generated less cash than it earned in profit — and needed outside funding despite trading well.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Operating working capital", h: "Operating current assets less operating current liabilities." },
      { t: "def", term: "Working capital cycle", h: "The time from paying for stock to collecting from customers." },
      { t: "def", term: "Cash release", h: "Cash freed when working capital falls." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Start of year: inventory ₹20L, receivables ₹15L, payables ₹12L. End: ₹28L, ₹21L, ₹16L. Compute working capital at both dates and the cash effect.", a: "Start: 23L. End: 33L. The ₹10L increase consumed ₹10 lakh of cash during a growth year." }, { q: "That year's profit was ₹8L. Did operations generate or consume cash overall?", a: "Roughly 8L − 10L = −₹2L: profitable trading, negative cash — the standard growth squeeze." }, { q: "Name one lever on each component that reduces working capital, and one risk of each.", a: "Hold less stock (stock-out risk), collect faster (customer friction), pay slower (supplier strain). Efficiency and relationships trade off." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "working-capital", title: "Working capital sandbox", prompt: "Scale inventory and receivables up 40% as if revenue grew — the rise you see is cash the growth demands.", fields: [{ key: "inventory", label: "Inventory", value: 2800000, unit: "₹" }, { key: "receivables", label: "Receivables", value: 2100000, unit: "₹" }, { key: "payables", label: "Payables", value: 1600000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Working capital is cash locked into operations.<br>• Growth increases working capital and therefore consumes cash.<br>• Profitable, fast-growing companies can and do run out of money this way." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Forgetting to fund working capital when planning growth.<br><br>Reading a working-capital reduction as an efficiency gain when it is actually collapsing sales." },
      { t: "mcq", q: "Operating working capital is…", opts: ["Cash in hand", "Inventory + receivables − payables", "Equity − debt", "Fixed assets"], correct: 1, why: ["Not this one. It is the net cash locked into running day-to-day operations.", "Correct. It is the net cash locked into running day-to-day operations.", "Not this one. It is the net cash locked into running day-to-day operations.", "Not this one. It is the net cash locked into running day-to-day operations."] },
      { t: "mcq", q: "When working capital increases over a period, cash is…", opts: ["Released", "Consumed", "Unaffected", "Doubled"], correct: 1, why: ["Not this one. More stock and unpaid invoices means more of your cash sitting inside operations.", "Correct. More stock and unpaid invoices means more of your cash sitting inside operations.", "Not this one. More stock and unpaid invoices means more of your cash sitting inside operations.", "Not this one. More stock and unpaid invoices means more of your cash sitting inside operations."] },
      { t: "mcq", q: "Fast profitable growth most commonly strains cash because…", opts: ["Taxes rise", "Working capital scales up ahead of collections", "Depreciation accelerates", "Interest rates rise"], correct: 1, why: ["Not this one. You buy stock and extend credit before the profits are collected — growth funds itself only later.", "Correct. You buy stock and extend credit before the profits are collected — growth funds itself only later.", "Not this one. You buy stock and extend credit before the profits are collected — growth funds itself only later.", "Not this one. You buy stock and extend credit before the profits are collected — growth funds itself only later."] }
    ]
  };

  LS.lessons["c-depreciation"] = {
    id: "c-depreciation", minutes: 5,
    title: "Depreciation",
    short: "Depreciation",
    desc: "Spreading the cost of a long-lived physical asset across the years it is used.",
    lede: "When a business buys something that will last several years — a machine, a vehicle, a building — charging the whole cost to the year of purchase would misrepresent that year and flatter every year afterwards.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "When a business buys something that will last several years — a machine, a vehicle, a building — charging the whole cost to the year of purchase would misrepresent that year and flatter every year afterwards. Depreciation spreads the cost across the asset's useful life instead. Cash leaves once; the expense is recognised gradually." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Depreciation is the largest non-cash expense in most asset-heavy businesses. Understanding it is what lets you reconcile profit to cash, and it is the reason measures like EBITDA exist at all." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Record the purchase as an asset, not an expense. Cash falls; the asset rises.<br><br>2. Estimate how long it will be useful and what it might be worth at the end.<br><br>3. Charge a portion of the cost as an expense each year over that life.<br><br>4. The asset's recorded value falls each year by the amount charged." },
      { t: "formula", title: "Annual depreciation charge under the straight-line method", lines: ["<b>Annual depreciation = (Cost − Residual value) ÷ Useful life</b>", "Cost = What was paid for the asset", "Residual value = Estimated value at the end of its useful life", "Useful life = Number of years it is expected to be used"] },
      { t: "example", h: "<p>A delivery van costs ₹12,00,000, is expected to last 6 years, and to be worth ₹1,20,000 at the end.</p><ol><li>Depreciable amount = ₹12,00,000 − ₹1,20,000 = ₹10,80,000.</li><li>Annual depreciation = ₹10,80,000 ÷ 6 = ₹1,80,000.</li><li>Year 1: expense ₹1,80,000; asset carried at ₹12,00,000 − ₹1,80,000 = ₹10,20,000.</li><li>Year 3: cumulative depreciation ₹5,40,000; asset carried at ₹6,60,000.</li></ol><p><strong>What it means.</strong> ₹12,00,000 of cash left in year one, but only ₹1,80,000 hit profit. In years 2 to 6, profit is reduced by ₹1,80,000 annually with no cash leaving at all. This is exactly why profit and cash flow diverge.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Useful life", h: "How long the asset is expected to be used — an estimate." },
      { t: "def", term: "Residual value", h: "Expected value at the end of the useful life." },
      { t: "def", term: "Straight-line method", h: "Charging an equal amount each year." },
      { t: "def", term: "Net book value", h: "Original cost less accumulated depreciation." },
      { t: "def", term: "Non-cash expense", h: "An expense that reduces profit without any cash leaving." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A van costs ₹12,00,000, lasts 6 years, residual ₹1,20,000. Compute the annual charge and the net book value after 3 years.", a: "Annual = (12,00,000 − 1,20,000) ÷ 6 = ₹1,80,000. After 3 years: NBV = 12,00,000 − 5,40,000 = ₹6,60,000." }, { q: "In which year did cash leave, and how much expense hits each of years 2–6?", a: "All ₹12,00,000 of cash left in year 1. Years 2–6 each carry ₹1,80,000 of expense with zero cash outflow — the core profit-vs-cash wedge." }, { q: "Management stretches the assumed life from 6 to 10 years. Effect on annual profit, and the risk?", a: "The charge drops to ₹1,08,000, lifting profit ₹72,000/year. If the van truly wears out in 6, later years absorb the truth via losses or write-offs — estimates are levers." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "depreciation", title: "Depreciation sandbox", prompt: "Stretch the useful life and watch the annual charge fall — then ask who is checking that estimate.", fields: [{ key: "cost", label: "Asset cost", value: 1200000, unit: "₹" }, { key: "residual", label: "Residual value", value: 120000, unit: "₹" }, { key: "usefulLife", label: "Useful life (years)", value: 6 }, { key: "yearsElapsed", label: "Years elapsed", value: 3 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Depreciation spreads a past cash outflow across the years of benefit.<br>• It reduces profit without reducing cash.<br>• Useful life and residual value are estimates, so depreciation involves judgement." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Treating depreciation as money being set aside — nothing is saved.<br><br>Assuming net book value reflects what the asset would sell for.<br><br>Thinking depreciation can be ignored because it is non-cash — the asset will eventually need replacing with real money." },
      { t: "mcq", q: "Depreciation exists to…", opts: ["Save cash for replacement", "Spread an asset's cost over the years it is used", "Track market value", "Reduce tax only"], correct: 1, why: ["Not this one. It matches the cost of a long-lived asset to the periods that benefit from it. No cash is set aside anywhere.", "Correct. It matches the cost of a long-lived asset to the periods that benefit from it. No cash is set aside anywhere.", "Not this one. It matches the cost of a long-lived asset to the periods that benefit from it. No cash is set aside anywhere.", "Not this one. It matches the cost of a long-lived asset to the periods that benefit from it. No cash is set aside anywhere."] },
      { t: "mcq", q: "Cost ₹5,00,000, residual ₹50,000, life 5 years. The straight-line annual charge is…", opts: ["₹1,00,000", "₹90,000", "₹1,10,000", "₹50,000"], correct: 1, why: ["Not this one. (5,00,000 − 50,000) ÷ 5 = ₹90,000.", "Correct. (5,00,000 − 50,000) ÷ 5 = ₹90,000.", "Not this one. (5,00,000 − 50,000) ÷ 5 = ₹90,000.", "Not this one. (5,00,000 − 50,000) ÷ 5 = ₹90,000."] },
      { t: "mcq", q: "Net book value equals…", opts: ["Resale price", "Original cost minus accumulated depreciation", "Replacement cost", "Insured value"], correct: 1, why: ["Not this one. It is an accounting remainder, not an appraisal — the market may pay far more or less.", "Correct. It is an accounting remainder, not an appraisal — the market may pay far more or less.", "Not this one. It is an accounting remainder, not an appraisal — the market may pay far more or less.", "Not this one. It is an accounting remainder, not an appraisal — the market may pay far more or less."] }
    ]
  };

  LS.lessons["c-amortization"] = {
    id: "c-amortization", minutes: 5,
    title: "Amortization",
    short: "Amortization",
    desc: "Depreciation's equivalent for intangible assets like software, patents and licences.",
    lede: "Amortisation is the same idea as depreciation, applied to assets you cannot touch: purchased software, patents, licences, customer contracts.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Amortisation is the same idea as depreciation, applied to assets you cannot touch: purchased software, patents, licences, customer contracts. The cost is spread across the period the asset is expected to be useful. The word differs only because the asset is intangible." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Intangible assets dominate the balance sheets of software, pharmaceutical and media businesses. In those companies amortisation, not depreciation, is the major non-cash charge, and it heavily affects reported profit." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Capitalise the cost of acquiring the intangible asset.<br><br>2. Estimate the period over which it will provide benefit — often set by a legal or contractual term.<br><br>3. Charge an equal portion as expense each year.<br><br>4. Some intangibles with no foreseeable end to their usefulness are not amortised, and are instead tested for impairment." },
      { t: "formula", title: "Annual amortisation charge", lines: ["<b>Annual amortisation = Cost ÷ Useful life</b>", "Cost = Amount paid to acquire the intangible asset", "Useful life = Years of expected benefit, often a legal or contract term"] },
      { t: "example", h: "<p>A company buys a 10-year patent licence for ₹50,00,000.</p><ol><li>Annual amortisation = ₹50,00,000 ÷ 10 = ₹5,00,000.</li><li>Year 1: expense ₹5,00,000; carrying value ₹45,00,000.</li><li>Year 5: cumulative ₹25,00,000; carrying value ₹25,00,000.</li><li>Cash outflow: ₹50,00,000, all in year 1.</li></ol><p><strong>What it means.</strong> The full ₹50 lakh left the bank immediately, but profit absorbs it at ₹5 lakh a year for a decade. Anyone comparing this company's profit to its cash generation must account for that difference.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Intangible asset", h: "A non-physical asset such as software, a patent or a licence." },
      { t: "def", term: "Amortisation", h: "Spreading an intangible asset's cost over its useful life." },
      { t: "def", term: "Impairment", h: "Writing an asset down when it is worth less than its carrying value." },
      { t: "def", term: "Indefinite life", h: "An intangible with no foreseeable end to its usefulness; tested rather than amortised." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "A 10-year patent licence costs ₹50,00,000. Annual amortisation, and carrying value after year 5?", a: "₹5,00,000 per year; carrying value ₹25,00,000 after five." }, { q: "When did the cash leave, and what does each later year's income statement show?", a: "₹50 lakh left in year 1. Years 2–10 each show ₹5,00,000 of amortisation with no cash movement." }, { q: "A loan officer says 'this loan amortises over 15 years'. Is that the same use of the word?", a: "No — loan amortisation means scheduled principal repayment. Asset amortisation spreads a cost. Same word, two meanings; context decides." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "depreciation", title: "Amortisation sandbox", prompt: "Set residual to zero (typical for licences) and step through the years of the charge.", fields: [{ key: "cost", label: "Licence cost", value: 5000000, unit: "₹" }, { key: "residual", label: "Residual value", value: 0, unit: "₹" }, { key: "usefulLife", label: "Useful life (years)", value: 10 }, { key: "yearsElapsed", label: "Years elapsed", value: 5 }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Amortisation is depreciation for intangible assets.<br>• It is a non-cash expense that reduces profit without reducing cash.<br>• Intangible-heavy businesses can show weak profit alongside strong cash generation." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Assuming intangible assets are unimportant because they are not physical.<br><br>Confusing amortisation of an asset with amortisation of a loan, which means scheduled principal repayment." },
      { t: "mcq", q: "Amortisation applies to…", opts: ["Buildings and vehicles", "Intangible assets like licences and patents", "Inventory", "Cash"], correct: 1, why: ["Not this one. It is depreciation's twin for assets without physical form.", "Correct. It is depreciation's twin for assets without physical form.", "Not this one. It is depreciation's twin for assets without physical form.", "Not this one. It is depreciation's twin for assets without physical form."] },
      { t: "mcq", q: "A ₹30,00,000 software licence with a 6-year life is amortised annually at…", opts: ["₹6,00,000", "₹5,00,000", "₹3,00,000", "₹30,00,000"], correct: 1, why: ["Not this one. 30,00,000 ÷ 6 = ₹5,00,000 per year.", "Correct. 30,00,000 ÷ 6 = ₹5,00,000 per year.", "Not this one. 30,00,000 ÷ 6 = ₹5,00,000 per year.", "Not this one. 30,00,000 ÷ 6 = ₹5,00,000 per year."] },
      { t: "mcq", q: "An intangible with an indefinite useful life is…", opts: ["Amortised over 10 years by default", "Tested periodically for impairment instead of amortised", "Expensed immediately", "Ignored"], correct: 1, why: ["Not this one. No foreseeable end to usefulness means no sensible life to spread over; impairment testing polices the value instead.", "Correct. No foreseeable end to usefulness means no sensible life to spread over; impairment testing polices the value instead.", "Not this one. No foreseeable end to usefulness means no sensible life to spread over; impairment testing polices the value instead.", "Not this one. No foreseeable end to usefulness means no sensible life to spread over; impairment testing polices the value instead."] }
    ]
  };

  LS.lessons["c-ppe"] = {
    id: "c-ppe", minutes: 5,
    title: "PP&E",
    short: "PP&E",
    desc: "Property, plant and equipment — the physical assets a business uses to operate.",
    lede: "PP&E stands for property, plant and equipment: land, buildings, machinery, vehicles, fittings.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "PP&E stands for property, plant and equipment: land, buildings, machinery, vehicles, fittings. These are assets the business uses to produce goods or services rather than assets it intends to sell. They are recorded at cost and then reduced each year by depreciation." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "PP&E tells you how capital-intensive a business is. A company needing ₹100 of equipment for every ₹100 of revenue is a fundamentally different investment from one needing ₹10, because it must keep spending to stay in business." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Buying PP&E is capital expenditure — cash out, asset up, no immediate expense.<br><br>2. Depreciation reduces the asset's carrying value and reduces profit each year.<br><br>3. The closing balance is roughly the opening balance plus new spending less depreciation.<br><br>4. Spending consistently below depreciation means the asset base is shrinking." },
      { t: "formula", title: "How the PP&E balance rolls forward across a period", lines: ["<b>Closing PP&E = Opening PP&E + Capital expenditure − Depreciation</b>", "Opening PP&E = Net book value at the start of the period", "Capital expenditure = Cash spent on new long-lived assets", "Depreciation = The charge for the period"] },
      { t: "example", h: "<p>A manufacturer opens the year with ₹80 crore of PP&E, spends ₹12 crore on new machinery and records ₹15 crore of depreciation.</p><ol><li>Closing PP&E = ₹80 crore + ₹12 crore − ₹15 crore = ₹77 crore.</li><li>The base shrank by ₹3 crore despite ₹12 crore of spending.</li><li>Repeat this for five years and the asset base falls to roughly ₹65 crore.</li></ol><p><strong>What it means.</strong> Spending less than depreciation means the equipment is wearing out faster than it is being replaced. Reported profit looks fine today, but the business is quietly consuming its own capacity.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Capital expenditure (capex)", h: "Cash spent acquiring or improving long-lived assets." },
      { t: "def", term: "Gross PP&E", h: "Original cost of all such assets before depreciation." },
      { t: "def", term: "Net PP&E", h: "Gross PP&E less accumulated depreciation." },
      { t: "def", term: "Maintenance capex", h: "Spending needed just to keep the existing asset base intact." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Opening PP&E ₹80 crore; capex ₹12 crore; depreciation ₹15 crore. Closing balance, and what it implies?", a: "80 + 12 − 15 = ₹77 crore. Spending below depreciation: the productive base shrank ₹3 crore this year." }, { q: "If that pattern repeats for five years, roughly where does the base end up, and what is the business quietly doing?", a: "Around ₹65 crore. It is consuming its own capacity — profit looks fine while future output erodes." }, { q: "Two firms each earn ₹20 crore. One needs ₹200 crore of PP&E, the other ₹20 crore. Why does the difference matter to an investor?", a: "The first must keep reinvesting heavily just to stand still, leaving less free cash. Capital intensity determines how much of profit ever reaches owners." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "ppe-rollforward", title: "Asset base sandbox", prompt: "Set capex below the depreciation charge and watch the warning appear.", fields: [{ key: "opening", label: "Opening PP&E", value: 800000000, unit: "₹" }, { key: "capex", label: "Capital expenditure", value: 120000000, unit: "₹" }, { key: "depreciationCharge", label: "Depreciation", value: 150000000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "PP&E is the physical asset base used to operate, not to sell.<br>• It rolls forward as opening balance plus capex less depreciation.<br>• Capex persistently below depreciation is a warning sign about future capacity." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Treating capex as an expense in the year it is paid.<br><br>Assuming net PP&E approximates market value.<br><br>Reading low capex as good cost discipline without checking whether assets are being run down." },
      { t: "mcq", q: "PP&E consists of assets…", opts: ["Held for resale", "Used to operate the business over many years", "Owned by suppliers", "That never lose value"], correct: 1, why: ["Not this one. Land, buildings, machinery, vehicles — the physical platform for producing goods and services.", "Correct. Land, buildings, machinery, vehicles — the physical platform for producing goods and services.", "Not this one. Land, buildings, machinery, vehicles — the physical platform for producing goods and services.", "Not this one. Land, buildings, machinery, vehicles — the physical platform for producing goods and services."] },
      { t: "mcq", q: "Closing PP&E equals…", opts: ["Opening + depreciation − capex", "Opening + capex − depreciation", "Opening × growth rate", "Capex alone"], correct: 1, why: ["Not this one. New investment adds; the period's depreciation subtracts.", "Correct. New investment adds; the period's depreciation subtracts.", "Not this one. New investment adds; the period's depreciation subtracts.", "Not this one. New investment adds; the period's depreciation subtracts."] },
      { t: "mcq", q: "Capex persistently below depreciation most likely means…", opts: ["Excellent efficiency", "The asset base is being run down", "Assets are appreciating", "Nothing"], correct: 1, why: ["Not this one. Equipment is wearing out faster than it is replaced — fine briefly, corrosive if sustained.", "Correct. Equipment is wearing out faster than it is replaced — fine briefly, corrosive if sustained.", "Not this one. Equipment is wearing out faster than it is replaced — fine briefly, corrosive if sustained.", "Not this one. Equipment is wearing out faster than it is replaced — fine briefly, corrosive if sustained."] }
    ]
  };

  LS.lessons["c-goodwill"] = {
    id: "c-goodwill", minutes: 5,
    title: "Goodwill",
    short: "Goodwill",
    desc: "The premium paid to buy a business above the value of its identifiable net assets.",
    lede: "Goodwill appears only when one business buys another.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Goodwill appears only when one business buys another. If the buyer pays more than the fair value of the identifiable assets less liabilities acquired, the excess is recorded as goodwill. It represents things that have value but cannot be listed separately: reputation, workforce, customer relationships, expected synergies." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Goodwill is the accounting record of what a buyer paid over identifiable value — in effect, a permanent public record of whether the price was justified. Large goodwill write-offs are usually an admission that an acquisition did not work out." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Measure the fair value of the identifiable assets and liabilities acquired.<br><br>2. Compare that to the purchase price paid.<br><br>3. Record the excess as goodwill on the buyer's balance sheet.<br><br>4. Goodwill is generally not amortised; it is tested periodically and written down if the business is worth less than carried." },
      { t: "formula", title: "The premium recorded on an acquisition", lines: ["<b>Goodwill = Purchase price − Fair value of identifiable net assets acquired</b>", "Purchase price = Total consideration paid for the business", "Fair value of identifiable net assets = Identifiable assets less liabilities, at fair value"] },
      { t: "example", h: "<p>Company A buys Company B for ₹500 crore. B's identifiable assets are worth ₹420 crore and its liabilities ₹150 crore.</p><ol><li>Identifiable net assets = ₹420 crore − ₹150 crore = ₹270 crore.</li><li>Goodwill = ₹500 crore − ₹270 crore = ₹230 crore.</li><li>Two years later B is struggling and judged to be worth ₹350 crore in total.</li><li>Goodwill is written down, producing a large non-cash loss in that year's profit.</li></ol><p><strong>What it means.</strong> The ₹230 crore was paid for expectations. If those expectations fail, the write-down does not remove any cash — the cash left at purchase — but it publicly records that the price was too high.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Fair value", h: "The amount an asset or liability would exchange for between willing parties." },
      { t: "def", term: "Identifiable net assets", h: "Assets and liabilities that can be recognised separately." },
      { t: "def", term: "Impairment", h: "Writing goodwill down when the acquired business is worth less than carried." },
      { t: "def", term: "Synergy", h: "Expected benefit from combining two businesses." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Company A pays ₹500 crore for Company B, whose identifiable assets are worth ₹420 crore and liabilities ₹150 crore. Compute goodwill.", a: "Identifiable net assets = 270 crore; goodwill = 500 − 270 = ₹230 crore." }, { q: "Two years on, B is judged worth ₹350 crore in total. What happens, and is cash involved?", a: "Goodwill is impaired — written down through a large non-cash loss. The cash left at purchase; the write-down is the public admission the price was too high." }, { q: "Why does a famous 50-year-old brand built in-house show ₹0 of goodwill on its own balance sheet?", a: "Internally generated goodwill is not recognised — only a purchase creates it. The brand's value is real but invisible in the accounts." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "goodwill", title: "Acquisition premium sandbox", prompt: "Raise the purchase price and watch the part of it that rests purely on expectations.", fields: [{ key: "purchasePrice", label: "Price paid", value: 5000000000, unit: "₹" }, { key: "assetsAcquired", label: "Identifiable assets", value: 4200000000, unit: "₹" }, { key: "liabilitiesAcquired", label: "Liabilities assumed", value: 1500000000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Goodwill only arises from acquiring another business.<br>• It is the excess of price paid over identifiable net assets.<br>• An impairment is non-cash but is a meaningful admission about a past decision." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Thinking a company can create goodwill from its own strong brand — internally generated goodwill is not recognised.<br><br>Dismissing impairments as irrelevant because they are non-cash." },
      { t: "mcq", q: "Goodwill arises only when…", opts: ["A brand becomes popular", "One business buys another for more than its identifiable net assets", "Profits are strong", "Auditors permit it"], correct: 1, why: ["Not this one. It is a purchase residual: price paid minus identifiable net assets at fair value.", "Correct. It is a purchase residual: price paid minus identifiable net assets at fair value.", "Not this one. It is a purchase residual: price paid minus identifiable net assets at fair value.", "Not this one. It is a purchase residual: price paid minus identifiable net assets at fair value."] },
      { t: "mcq", q: "Price ₹800 crore; identifiable assets ₹700 crore; liabilities ₹250 crore. Goodwill is…", opts: ["₹100 crore", "₹350 crore", "₹550 crore", "₹250 crore"], correct: 1, why: ["Not this one. Net assets = 450; goodwill = 800 − 450 = ₹350 crore.", "Correct. Net assets = 450; goodwill = 800 − 450 = ₹350 crore.", "Not this one. Net assets = 450; goodwill = 800 − 450 = ₹350 crore.", "Not this one. Net assets = 450; goodwill = 800 − 450 = ₹350 crore."] },
      { t: "mcq", q: "A goodwill impairment is best read as…", opts: ["A cash outflow today", "A non-cash admission that the acquisition price was not justified", "A tax refund", "Routine depreciation"], correct: 1, why: ["Not this one. No cash moves at impairment, but the signal about a past capital-allocation decision is very real.", "Correct. No cash moves at impairment, but the signal about a past capital-allocation decision is very real.", "Not this one. No cash moves at impairment, but the signal about a past capital-allocation decision is very real.", "Not this one. No cash moves at impairment, but the signal about a past capital-allocation decision is very real."] }
    ]
  };

  LS.lessons["c-intangible-assets"] = {
    id: "c-intangible-assets", minutes: 5,
    title: "Intangible assets",
    short: "Intangible assets",
    desc: "Assets with real value that you cannot physically touch.",
    lede: "Intangible assets are non-physical resources expected to produce future benefit: patents, trademarks, licences, purchased software, customer lists.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Intangible assets are non-physical resources expected to produce future benefit: patents, trademarks, licences, purchased software, customer lists. They are recognised when they are identifiable and were acquired or developed under conditions the accounting rules permit. Crucially, most internally built brand value never appears on a balance sheet at all." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "In modern economies much of a company's real value is intangible, yet accounting recognises only part of it. This is why market values and book values diverge most dramatically for software, consumer-brand and pharmaceutical companies." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Purchased intangibles are recorded at cost and usually amortised over their useful life.<br><br>2. Internally generated brands and most research spending are expensed as incurred, not capitalised.<br><br>3. Some development costs may be capitalised if strict criteria are met.<br><br>4. Intangibles with indefinite lives are tested for impairment rather than amortised." },
      { t: "example", h: "<p>Two consumer companies, each with a brand a valuer would price at ₹1,000 crore.</p><ol><li>Company X built its brand over 40 years of advertising, all expensed as incurred.</li><li>Company Y acquired an identical brand for ₹1,000 crore in an acquisition.</li><li>X's balance sheet shows ₹0 of brand value. Y's shows ₹1,000 crore.</li></ol><p><strong>What it means.</strong> Two economically identical assets, one visible and one invisible. This is why book value is a poor guide to worth for brand-driven businesses, and why comparing them on book-value ratios can mislead.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Identifiable intangible", h: "An intangible that can be separated and valued on its own." },
      { t: "def", term: "Internally generated intangible", h: "One built by the business itself, usually not recognised." },
      { t: "def", term: "Useful life", h: "The period over which an intangible is expected to provide benefit." },
      { t: "def", term: "Research and development", h: "Spending on new products; research is expensed, development sometimes capitalised." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Two companies own economically identical ₹1,000 crore brands — one built over 40 years, one just purchased. What does each balance sheet show, and why?", a: "Built: ₹0 (internal brand spending was expensed as incurred). Purchased: ₹1,000 crore (acquired intangibles are recognised at cost). Same asset, opposite visibility." }, { q: "Why is a price-to-book comparison between a software firm and a steel maker close to meaningless?", a: "The software firm's main assets (code, brand, users) are largely unrecognised; the steel maker's plant is on the books. The 'book' being compared measures different fractions of real value." }, { q: "Research spending versus qualifying development spending — how do the treatments differ?", a: "Research is expensed as incurred; development may be capitalised only when strict criteria (technical feasibility, intention, probable benefit) are demonstrably met." }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Intangibles can be a company's most valuable assets while being largely absent from its balance sheet.<br>• Acquired intangibles are recognised; internally built ones usually are not.<br>• Book value understates worth most severely for intangible-heavy businesses." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Assuming a low book value means few valuable assets.<br><br>Comparing book-value ratios across companies with very different intangible profiles." },
      { t: "where", h: "Which development costs may be capitalised differs between accounting frameworks (IFRS/Ind AS versus US GAAP) and is subject to revision. Check the framework a company reports under." },
      { t: "mcq", q: "Which appears on the balance sheet?", opts: ["A brand built through decades of own advertising", "A brand acquired in a takeover", "Employee loyalty", "Founder reputation"], correct: 1, why: ["Not this one. Acquisition creates a measurable cost to recognise; internal generation does not.", "Correct. Acquisition creates a measurable cost to recognise; internal generation does not.", "Not this one. Acquisition creates a measurable cost to recognise; internal generation does not.", "Not this one. Acquisition creates a measurable cost to recognise; internal generation does not."] },
      { t: "mcq", q: "For brand-heavy and software businesses, book value tends to…", opts: ["Overstate real value", "Understate it, because key intangibles go unrecognised", "Match market value", "Equal liquidation value"], correct: 1, why: ["Not this one. The most valuable assets are precisely the ones accounting leaves off.", "Correct. The most valuable assets are precisely the ones accounting leaves off.", "Not this one. The most valuable assets are precisely the ones accounting leaves off.", "Not this one. The most valuable assets are precisely the ones accounting leaves off."] },
      { t: "mcq", q: "A purchased intangible with a 10-year contractual life is usually…", opts: ["Never touched", "Amortised over the 10 years", "Impaired immediately", "Revalued upward yearly"], correct: 1, why: ["Not this one. A defined benefit period gives a defined life to spread cost over.", "Correct. A defined benefit period gives a defined life to spread cost over.", "Not this one. A defined benefit period gives a defined life to spread cost over.", "Not this one. A defined benefit period gives a defined life to spread cost over."] }
    ]
  };

  LS.lessons["c-retained-earnings"] = {
    id: "c-retained-earnings", minutes: 5,
    title: "Retained earnings",
    short: "Retained earnings",
    desc: "The running total of all profits the business has kept rather than paid out to owners.",
    lede: "Retained earnings is the accumulated total of every profit the business has ever made, less every loss and every dividend paid.",
    body: [
      { t: "h2", text: "What is this?" },
      { t: "p", h: "Retained earnings is the accumulated total of every profit the business has ever made, less every loss and every dividend paid. It sits inside equity and is the link between the income statement and the balance sheet: this year's profit flows into it, increasing the owners' stake." },
      { t: "h2", text: "Why does it matter?" },
      { t: "p", h: "Retained earnings is the connection point that makes the three financial statements tie together. It is also the cheapest source of funding a business has — profit it already owns, requiring no borrowing and no new shares." },
      { t: "h2", text: "How does it work?" },
      { t: "p", h: "1. Start with the retained earnings balance from the end of last period.<br><br>2. Add this period's net profit, or subtract the loss.<br><br>3. Subtract any dividends declared to owners.<br><br>4. The result is the closing balance, which appears within equity." },
      { t: "formula", title: "How retained earnings roll forward between periods", lines: ["<b>Closing retained earnings = Opening retained earnings + Net profit − Dividends</b>", "Opening retained earnings = Accumulated retained profit at the start", "Net profit = Profit for the period after all costs, interest and tax", "Dividends = Profit distributed to owners during the period"] },
      { t: "example", h: "<p>A company opens the year with ₹45 crore of retained earnings, earns ₹12 crore and pays a ₹4 crore dividend.</p><ol><li>Closing retained earnings = ₹45 crore + ₹12 crore − ₹4 crore = ₹53 crore.</li><li>Equity rises by ₹8 crore without any new investment from owners.</li><li>The following year it makes a ₹6 crore loss and pays no dividend: ₹53 crore − ₹6 crore = ₹47 crore.</li></ol><p><strong>What it means.</strong> A large retained earnings balance means the business has been profitable and has kept those profits. It does not mean there is cash available — that money was long ago spent on stock, equipment and receivables.</p>" },
      { t: "h2", text: "Key terms" },
      { t: "def", term: "Retained earnings", h: "Cumulative profits kept in the business rather than distributed." },
      { t: "def", term: "Dividend", h: "A distribution of profit to owners." },
      { t: "def", term: "Accumulated deficit", h: "A negative retained earnings balance, from cumulative losses." },
      { t: "def", term: "Payout ratio", h: "The share of profit paid out as dividends." },
      { t: "h2", text: "Practice" },
      { t: "practice", items: [{ q: "Opening retained earnings ₹45 crore; profit ₹12 crore; dividend ₹4 crore. Closing balance?", a: "45 + 12 − 4 = ₹53 crore." }, { q: "The next year brings a ₹6 crore loss and no dividend. Balance now?", a: "53 − 6 = ₹47 crore. Losses subtract exactly as profits add." }, { q: "A firm shows ₹500 crore of retained earnings and ₹8 crore of cash. Reconcile the apparent contradiction.", a: "No contradiction: retained earnings track profits kept over the firm's life, long since reinvested in stock, equipment and receivables. It is history, not a bank balance." }] },
      { t: "h2", text: "Sandbox" },
      { t: "sandbox", kind: "retained", title: "Retention sandbox", prompt: "Pay out more than you earn and watch the balance fall — retained earnings are a running total, not a vault.", fields: [{ key: "opening", label: "Opening retained earnings", value: 450000000, unit: "₹" }, { key: "netProfit", label: "Profit for the year", value: 120000000, unit: "₹" }, { key: "dividends", label: "Dividends paid", value: 40000000, unit: "₹" }] },
      { t: "h2", text: "What to remember" },
      { t: "note", h: "Retained earnings accumulate profit less dividends over the company's whole life.<br>• It is the link that carries the income statement result onto the balance sheet.<br>• A large balance says nothing about available cash." },
      { t: "h2", text: "Common mistakes" },
      { t: "p", h: "Assuming retained earnings sit in a bank account somewhere.<br><br>Forgetting that dividends reduce equity without ever appearing in the income statement." },
      { t: "mcq", q: "Retained earnings grow when the company…", opts: ["Borrows", "Earns profit and keeps it", "Pays dividends", "Issues shares"], correct: 1, why: ["Not this one. The roll-forward is opening + profit − dividends; only kept profit adds.", "Correct. The roll-forward is opening + profit − dividends; only kept profit adds.", "Not this one. The roll-forward is opening + profit − dividends; only kept profit adds.", "Not this one. The roll-forward is opening + profit − dividends; only kept profit adds."] },
      { t: "mcq", q: "Dividends appear…", opts: ["On the income statement as an expense", "As a reduction of retained earnings, never as an expense", "As revenue to the company", "Nowhere"], correct: 1, why: ["Not this one. A dividend is a distribution of profit to owners, not a cost of earning it.", "Correct. A dividend is a distribution of profit to owners, not a cost of earning it.", "Not this one. A dividend is a distribution of profit to owners, not a cost of earning it.", "Not this one. A dividend is a distribution of profit to owners, not a cost of earning it."] },
      { t: "mcq", q: "The link carrying the income statement's result onto the balance sheet is…", opts: ["Cash", "Retained earnings", "Payables", "Goodwill"], correct: 1, why: ["Not this one. Net profit flows into retained earnings inside equity — the joint that ties the statements together.", "Correct. Net profit flows into retained earnings inside equity — the joint that ties the statements together.", "Not this one. Net profit flows into retained earnings inside equity — the joint that ties the statements together.", "Not this one. Net profit flows into retained earnings inside equity — the joint that ties the statements together."] }
    ]
  };
